# -*- coding: utf-8 -*-

from odoo import models, fields, api

class event_event(models.Model):
    _inherit = 'event.event'

    @api.depends('related_program_ids')
    def _get_related_data(self):
        for rec in self:
            if len(rec.related_program_ids) > 0:
                rec.komisi_id = rec.related_program_ids[0].komisi_id.id
                rec.bidang_id = rec.related_program_ids[0].bidang_id.id
            else:
                rec.komisi_id = False
                rec.bidang_id = False

    related_program_ids = fields.Many2many(comodel_name='cms.program', string='Program Kerja Terkait')
    komisi_id = fields.Many2one(comodel_name='cms.komisi', string='Komisi', compute='_get_related_data', store=True)
    bidang_id = fields.Many2one(comodel_name='cms.bidang', string='Bidang', compute='_get_related_data', store=True)

# -*- coding: utf-8 -*-

import logging
from odoo import http
from odoo.http import request

_logger = logging.getLogger(__name__)


class PublicProgramController(http.Controller):
    """Public controller for PIN-based program form access.

    Flow:
    1. User opens  /program/public/<token>
    2. If no valid session, show PIN entry page
    3. On correct PIN, set session flag and redirect to form
    4. Form shows program description fields; user fills them
    5. On submit, save data and show confirmation
    6. User can also manage program lines (create, edit, delete)
    """

    # Writable description fields on cms.program
    WRITABLE_FIELDS = [
        'description_background',
        'description_goal',
        'description_goal_indicators',
        'description_targets',
        'description_activities',
        'description_steps',
        'description_location',
        'description_time',
        'description_mission_relation',
    ]

    # Writable fields on cms.program.line
    LINE_WRITABLE_FIELDS = [
        'name', 'description', 'qty1', 'qty2', 'qty3',
        'cost_unit', 'exclude_fund_request',
        'analytic_account_id', 'budget_reference_id',
    ]

    def _get_program_by_token(self, token):
        """Lookup the program record by access_token."""
        Program = request.env['cms.program'].sudo()
        program = Program.search([
            ('access_token', '=', token),
        ], limit=1)
        return program

    def _session_key(self, token):
        return 'program_pin_verified_%s' % token

    def _get_form_context(self, token, program, **extra):
        """Build common context for the form template."""
        is_closed = program.state == 'closed'

        # Dropdown options for tag_ids, analytic_account
        tag_ids = request.env['cms.program.tag'].sudo().search([])
        analytic_accounts = request.env['account.analytic.account'].sudo().search([])
        budget_references = request.env['cms.budget.reference'].sudo().search([
            ('fiscalyear_id', '=', program.fiscalyear_id.id),
        ])

        # Misi, Tujuan, Strategi options
        misi_options = request.env['cms.misi'].sudo().search([])
        goal_options = request.env['cms.misi.goal'].sudo().search([])
        strategy_options = request.env['cms.misi.strategy'].sudo().search([])

        # Build relationship maps for JS cascading filter
        import json
        goal_misi_map = {str(g.id): g.misi_id.id for g in goal_options if g.misi_id}
        strategy_goal_map = {str(s.id): s.goal_id.id for s in strategy_options if s.goal_id}

        ctx = {
            'token': token,
            'program': program,
            'is_closed': is_closed,
            'tag_options': tag_ids,
            'analytic_options': analytic_accounts,
            'budget_ref_options': budget_references,
            'misi_options': misi_options,
            'goal_options': goal_options,
            'strategy_options': strategy_options,
            'goal_misi_map_json': json.dumps(goal_misi_map),
            'strategy_goal_map_json': json.dumps(strategy_goal_map),
        }
        ctx.update(extra)
        return ctx

    @http.route('/program/public/<string:token>', type='http', auth='public',
                website=True, csrf=False)
    def public_program_entry(self, token, **kwargs):
        """Entry point: show PIN page or redirect to form if already verified."""
        program = self._get_program_by_token(token)
        if not program:
            return request.render(
                'church_program.public_program_not_found', {}
            )

        # Check if PIN already verified in session
        session_key = self._session_key(token)
        if request.session.get(session_key):
            return request.redirect('/program/public/%s/form' % token)

        return request.render(
            'church_program.public_program_pin_page', {
                'token': token,
                'program': program,
                'error': kwargs.get('error', ''),
            }
        )

    @http.route('/program/public/<string:token>/verify', type='http',
                auth='public', website=True, csrf=False, methods=['POST'])
    def public_program_verify_pin(self, token, **kwargs):
        """Verify PIN and set session flag."""
        program = self._get_program_by_token(token)
        if not program:
            return request.render(
                'church_program.public_program_not_found', {}
            )

        pin = kwargs.get('pin', '').strip()
        if pin and pin == program.access_pin:
            session_key = self._session_key(token)
            request.session[session_key] = True
            return request.redirect('/program/public/%s/form' % token)
        else:
            return request.render(
                'church_program.public_program_pin_page', {
                    'token': token,
                    'program': program,
                    'error': 'PIN yang Anda masukkan salah. Silakan coba lagi.',
                }
            )

    @http.route('/program/public/<string:token>/form', type='http',
                auth='public', website=True, csrf=False)
    def public_program_form(self, token, **kwargs):
        """Show the program form with description fields and program lines."""
        program = self._get_program_by_token(token)
        if not program:
            return request.render(
                'church_program.public_program_not_found', {}
            )

        # Verify session
        session_key = self._session_key(token)
        if not request.session.get(session_key):
            return request.redirect('/program/public/%s' % token)

        ctx = self._get_form_context(token, program,
                                     success=kwargs.get('success', ''),
                                     line_success=kwargs.get('line_success', ''),
                                     line_deleted=kwargs.get('line_deleted', ''),
                                     error=kwargs.get('error', ''))
        return request.render('church_program.public_program_form', ctx)

    @http.route('/program/public/<string:token>/print', type='http',
                auth='public', website=True, csrf=False)
    def public_program_print(self, token, **kwargs):
        """Generate and download PDF report for the program."""
        program = self._get_program_by_token(token)
        if not program:
            return request.render(
                'church_program.public_program_not_found', {}
            )

        # Verify session
        session_key = self._session_key(token)
        if not request.session.get(session_key):
            return request.redirect('/program/public/%s' % token)

        # Render QWeb PDF via wkhtmltopdf
        report_ref = 'church_program.report_program_kerja'
        pdf_content, _content_type = request.env['ir.actions.report'].sudo()._render_qweb_pdf(
            report_ref, [program.id]
        )

        filename = 'Program Kerja - %s - %s.pdf' % (
            program.code or '', program.name or ''
        )

        return request.make_response(
            pdf_content,
            headers=[
                ('Content-Type', 'application/pdf'),
                ('Content-Disposition', 'attachment; filename="%s"' % filename),
            ]
        )

    @http.route('/program/public/<string:token>/submit', type='http',
                auth='public', website=True, csrf=False, methods=['POST'])
    def public_program_submit(self, token, **kwargs):
        """Save program form data."""
        program = self._get_program_by_token(token)
        if not program:
            return request.render(
                'church_program.public_program_not_found', {}
            )

        # Verify session
        session_key = self._session_key(token)
        if not request.session.get(session_key):
            return request.redirect('/program/public/%s' % token)

        # Check if program is closed
        if program.state == 'closed':
            return request.redirect(
                '/program/public/%s/form?error=closed' % token
            )

        update_vals = {}

        # Process writable description fields
        for field_name in self.WRITABLE_FIELDS:
            val = kwargs.get(field_name)
            if val is not None:
                update_vals[field_name] = val

        # Process many2many fields from comma-separated hidden inputs
        # Template sends: misi_ids_csv="1,3,5", goal_ids_csv="2", etc.
        for field, key in [
            ('misi_ids', 'misi_ids_csv'),
            ('goal_ids', 'goal_ids_csv'),
            ('strategy_ids', 'strategy_ids_csv'),
        ]:
            csv_val = kwargs.get(key, '')
            int_vals = []
            if csv_val:
                for v in csv_val.split(','):
                    v = v.strip()
                    if v:
                        try:
                            int_vals.append(int(v))
                        except (ValueError, TypeError):
                            pass
            _logger.info(
                "Public program %s: field=%s, csv=%r, parsed=%s",
                token, field, csv_val, int_vals
            )
            update_vals[field] = [(6, 0, int_vals)]

        if update_vals:
            program.sudo().write(update_vals)

        # Post a message on the chatter
        program.sudo().message_post(
            body="Program kerja diisi/diperbarui melalui form publik (PIN).",
            message_type='comment',
            subtype_xmlid='mail.mt_note',
        )

        return request.redirect(
            '/program/public/%s/form?success=1' % token
        )

    # ===================================================================
    # Program Line CRUD
    # ===================================================================

    def _parse_line_vals(self, kwargs):
        """Parse and validate line form values from POST data."""
        vals = {}
        vals['name'] = (kwargs.get('line_name') or '').strip()
        vals['description'] = (kwargs.get('line_description') or '').strip()

        # Numeric fields
        for field, key, default in [
            ('qty1', 'line_qty1', 1),
            ('qty2', 'line_qty2', 1),
            ('qty3', 'line_qty3', 1),
        ]:
            try:
                vals[field] = int(kwargs.get(key, default))
            except (ValueError, TypeError):
                vals[field] = default

        try:
            vals['cost_unit'] = float(kwargs.get('line_cost_unit', 0))
        except (ValueError, TypeError):
            vals['cost_unit'] = 0

        # Boolean
        vals['exclude_fund_request'] = kwargs.get('line_exclude_fund_request') == '1'

        # Many2one fields
        for field, key in [
            ('analytic_account_id', 'line_analytic_account_id'),
            ('budget_reference_id', 'line_budget_reference_id'),
        ]:
            try:
                val = int(kwargs.get(key, 0) or 0)
                vals[field] = val if val else False
            except (ValueError, TypeError):
                vals[field] = False

        # Many2many tag_ids
        tag_values = kwargs.getlist('line_tag_ids') if hasattr(kwargs, 'getlist') else []
        if not tag_values:
            # Fallback: werkzeug ImmutableMultiDict
            tag_values = request.httprequest.form.getlist('line_tag_ids')
        if tag_values:
            tag_int = []
            for t in tag_values:
                try:
                    tag_int.append(int(t))
                except (ValueError, TypeError):
                    pass
            vals['tag_ids'] = [(6, 0, tag_int)]
        else:
            vals['tag_ids'] = [(5, 0, 0)]  # clear

        return vals

    @http.route('/program/public/<string:token>/line/add', type='http',
                auth='public', website=True, csrf=False, methods=['POST'])
    def public_program_line_add(self, token, **kwargs):
        """Create a new program line."""
        program = self._get_program_by_token(token)
        if not program:
            return request.render('church_program.public_program_not_found', {})

        session_key = self._session_key(token)
        if not request.session.get(session_key):
            return request.redirect('/program/public/%s' % token)

        if program.state == 'closed':
            return request.redirect('/program/public/%s/form?error=closed' % token)

        vals = self._parse_line_vals(kwargs)
        vals['program_id'] = program.id

        # Compute subtotal
        vals['amount_subtotal'] = vals['qty1'] * vals['qty2'] * vals['qty3'] * vals['cost_unit']

        request.env['cms.program.line'].sudo().create(vals)
        program.sudo()._calculate_total()

        return request.redirect('/program/public/%s/form?line_success=added' % token)

    @http.route('/program/public/<string:token>/line/<int:line_id>/edit', type='http',
                auth='public', website=True, csrf=False, methods=['POST'])
    def public_program_line_edit(self, token, line_id, **kwargs):
        """Update an existing program line."""
        program = self._get_program_by_token(token)
        if not program:
            return request.render('church_program.public_program_not_found', {})

        session_key = self._session_key(token)
        if not request.session.get(session_key):
            return request.redirect('/program/public/%s' % token)

        if program.state == 'closed':
            return request.redirect('/program/public/%s/form?error=closed' % token)

        # Verify line belongs to this program
        line = request.env['cms.program.line'].sudo().browse(line_id)
        if not line.exists() or line.program_id.id != program.id:
            return request.redirect('/program/public/%s/form?error=line_not_found' % token)

        vals = self._parse_line_vals(kwargs)

        line.sudo().write(vals)
        program.sudo()._calculate_total()

        return request.redirect('/program/public/%s/form?line_success=updated' % token)

    @http.route('/program/public/<string:token>/line/<int:line_id>/delete', type='http',
                auth='public', website=True, csrf=False, methods=['POST'])
    def public_program_line_delete(self, token, line_id, **kwargs):
        """Delete a program line."""
        program = self._get_program_by_token(token)
        if not program:
            return request.render('church_program.public_program_not_found', {})

        session_key = self._session_key(token)
        if not request.session.get(session_key):
            return request.redirect('/program/public/%s' % token)

        if program.state == 'closed':
            return request.redirect('/program/public/%s/form?error=closed' % token)

        # Verify line belongs to this program
        line = request.env['cms.program.line'].sudo().browse(line_id)
        if not line.exists() or line.program_id.id != program.id:
            return request.redirect('/program/public/%s/form?error=line_not_found' % token)

        line_name = line.name or 'item'
        line.sudo().unlink()
        program.sudo()._calculate_total()

        return request.redirect('/program/public/%s/form?line_deleted=1' % token)

