from odoo import models, fields, api

class cms_komisi(models.Model):
    _inherit = 'cms.komisi'

    program_ids = fields.One2many(comodel_name='cms.program', inverse_name='komisi_id', string='Program Kerja')
    komisi_year_ids = fields.One2many(comodel_name='komisi.year', inverse_name='komisi_id', string='Tahun Program')
    default_journal_id = fields.Many2one(comodel_name='account.journal', string='Jurnal Laporan Keuangan')
    default_account_id = fields.Many2one(comodel_name='account.account', string='Kode Akun Keuangan')

    def action_program_confirm(self):
        for rec in self:
            for program in rec.program_ids:
                program.action_confirm()

    def action_budget_month_line_summarize(self):
        for rec in self:
            for program in rec.program_ids:
                program.action_budget_month_line_summarize()

    def action_generate_default_journal(self):
        for rec in self:
            account_data = {
                "name" : "KAS: " + rec.name,
                "code" : "C" + rec.code,
                "account_type" : "asset_cash",
            }
            accounts = self.env["account.account"].search([("name","=",account_data["name"])])
            if len(accounts) == 0:
                accounts = self.env["account.account"].create(account_data)
            #if len(accounts) == 1:
            #    accounts = self.env["account.account"].write(accounts[0].id, account_data)
            self.default_account_id = accounts[0].id            

            journal_data = {
                "name" : rec.name,
                "type" : "cash",
                "code" : "CJ" + rec.code,
                "default_account_id" : accounts[0].id,
            }
            journals = self.env["account.journal"].search([("name","=",journal_data["name"])])
            if len(journals) == 0:
                journals = self.env["account.journal"].create(journal_data)
            if len(journals) == 1:
                #journals = self.env["account.journal"].write(journals[0].id, journal_data)
                journals[0].default_account_id = accounts[0].id
            self.default_journal_id = journals[0].id

