# -*- coding: utf-8 -*-

import logging
from odoo import http
from odoo.http import request

_logger = logging.getLogger(__name__)


class PublicProgramStatusController(http.Controller):
    """Public controller for program status overview (no PIN required).

    Shows program status (Draft/Confirmed/Active/Closed) per fiscal year
    grouped by Bidang > Komisi, WITHOUT any financial amounts.

    Since no financial data is exposed, this page is openly accessible
    via the token URL without PIN verification.
    """

    def _get_fiscalyear_by_token(self, token):
        """Lookup the fiscal year record by public_access_token."""
        FiscalYear = request.env['account.fiscal.year'].sudo()
        fy = FiscalYear.search([
            ('public_access_token', '=', token),
        ], limit=1)
        return fy

    def _build_status_data(self, fiscalyear):
        """Build status overview data grouped by Bidang > Komisi > Program."""
        programs = fiscalyear.program_ids.sorted(key=lambda p: p.code or '')

        # Description fields to check completeness
        desc_fields = [
            'description_background',
            'description_goal',
            'description_goal_indicators',
            'description_targets',
            'description_activities',
            'description_steps',
            'description_location',
            'description_time',
        ]

        # Status counters
        status_counts = {'draft': 0, 'confirmed': 0, 'open': 0, 'closed': 0}

        bidang_map = {}
        for prog in programs:
            bid = prog.bidang_id
            kom = prog.komisi_id

            state = prog.state or 'draft'
            status_counts[state] = status_counts.get(state, 0) + 1

            # Check description completeness
            filled_descs = sum(
                1 for f in desc_fields
                if getattr(prog, f, None)
                and str(getattr(prog, f, '')).strip()
                and str(getattr(prog, f, '')).strip() != 'False'
            )
            has_descriptions = filled_descs > 0
            desc_progress = int((filled_descs / len(desc_fields)) * 100) if desc_fields else 0

            # Check if budget lines exist
            has_lines = bool(prog.line_ids)
            line_count = len(prog.line_ids)

            # Check review status on program lines
            review_lines = prog.line_ids.filtered(lambda l: l.to_review)
            review_count = len(review_lines)
            review_notes = []
            for rl in review_lines:
                note = rl.note_review or ''
                review_notes.append({
                    'line_name': rl.name or '',
                    'note': note.strip(),
                })

            prog_data = {
                'program': prog,
                'code': prog.code or '',
                'name': prog.name or '',
                'state': state,
                'program_type': prog.program_type or 'rutin',
                'has_descriptions': has_descriptions,
                'desc_progress': desc_progress,
                'filled_descs': filled_descs,
                'total_descs': len(desc_fields),
                'has_lines': has_lines,
                'line_count': line_count,
                'has_misi': bool(prog.misi_ids),
                'has_goals': bool(prog.goal_ids),
                'has_strategies': bool(prog.strategy_ids),
                'review_count': review_count,
                'review_notes': review_notes,
            }

            if bid.id not in bidang_map:
                bidang_map[bid.id] = {
                    'bidang': bid,
                    'komisi_map': {},
                    'program_count': 0,
                    'status_counts': {'draft': 0, 'confirmed': 0, 'open': 0, 'closed': 0},
                }

            bd = bidang_map[bid.id]
            bd['program_count'] += 1
            bd['status_counts'][state] = bd['status_counts'].get(state, 0) + 1

            if kom.id not in bd['komisi_map']:
                bd['komisi_map'][kom.id] = {
                    'komisi': kom,
                    'programs': [],
                    'program_count': 0,
                    'status_counts': {'draft': 0, 'confirmed': 0, 'open': 0, 'closed': 0},
                }

            km = bd['komisi_map'][kom.id]
            km['programs'].append(prog_data)
            km['program_count'] += 1
            km['status_counts'][state] = km['status_counts'].get(state, 0) + 1

        # Convert to sorted lists
        bidang_list = []
        for bid_id in sorted(bidang_map.keys()):
            bd = bidang_map[bid_id]
            komisi_list = []
            for kom_id in sorted(bd['komisi_map'].keys()):
                komisi_list.append(bd['komisi_map'][kom_id])
            bd['komisi_list'] = komisi_list
            del bd['komisi_map']
            bidang_list.append(bd)

        bidang_list.sort(key=lambda b: b['bidang'].code or '')

        summary = {
            'total_programs': len(programs),
            'status_counts': status_counts,
            'confirmed_pct': int(
                ((status_counts.get('confirmed', 0) + status_counts.get('open', 0) + status_counts.get('closed', 0))
                 / len(programs) * 100)
            ) if programs else 0,
        }

        return {
            'fiscalyear': fiscalyear,
            'bidang_list': bidang_list,
            'summary': summary,
        }

    @http.route('/program-status/<string:token>', type='http', auth='public',
                website=True, csrf=False)
    def public_program_status_entry(self, token, **kwargs):
        """Entry point: redirect directly to status view (no PIN required)."""
        fy = self._get_fiscalyear_by_token(token)
        if not fy or not fy.public_status_active:
            return request.render(
                'church_program.public_program_status_not_found', {}
            )

        return request.redirect('/program-status/%s/view' % token)

    @http.route('/program-status/<string:token>/view', type='http',
                auth='public', website=True, csrf=False)
    def public_program_status_view(self, token, **kwargs):
        """Render the program status overview page (no PIN required)."""
        fy = self._get_fiscalyear_by_token(token)
        if not fy or not fy.public_status_active:
            return request.render(
                'church_program.public_program_status_not_found', {}
            )

        status_data = self._build_status_data(fy)

        return request.render(
            'church_program.public_program_status_page', {
                'token': token,
                'fiscalyear': fy,
                'status_data': status_data,
                'company': request.env.company,
            }
        )

    def _build_status_json(self, fiscalyear):
        """Convert status data to a JSON-serializable dict (no ORM objects)."""
        raw = self._build_status_data(fiscalyear)

        bidang_list = []
        for bd in raw['bidang_list']:
            komisi_list = []
            for km in bd['komisi_list']:
                programs = []
                for pd in km['programs']:
                    programs.append({
                        'code': pd['code'],
                        'name': pd['name'],
                        'state': pd['state'],
                        'program_type': pd['program_type'],
                        'has_descriptions': pd['has_descriptions'],
                        'desc_progress': pd['desc_progress'],
                        'filled_descs': pd['filled_descs'],
                        'total_descs': pd['total_descs'],
                        'has_lines': pd['has_lines'],
                        'line_count': pd['line_count'],
                        'review_count': pd.get('review_count', 0),
                        'review_notes': pd.get('review_notes', []),
                    })
                komisi_list.append({
                    'komisi_name': km['komisi'].name or 'Komisi',
                    'program_count': km['program_count'],
                    'status_counts': km['status_counts'],
                    'programs': programs,
                })
            bidang_list.append({
                'bidang_id': bd['bidang'].id,
                'bidang_code': bd['bidang'].code or '-',
                'bidang_name': bd['bidang'].name or 'Bidang',
                'program_count': bd['program_count'],
                'status_counts': bd['status_counts'],
                'komisi_list': komisi_list,
            })

        return {
            'fiscalyear_name': fiscalyear.name,
            'summary': raw['summary'],
            'bidang_list': bidang_list,
        }

    @http.route('/program-status/<string:token>/api', type='http',
                auth='public', website=True, csrf=False)
    def public_program_status_api(self, token, **kwargs):
        """JSON API endpoint for AJAX refresh of status data (no PIN required)."""
        import json as json_lib

        fy = self._get_fiscalyear_by_token(token)
        if not fy or not fy.public_status_active:
            return request.make_response(
                json_lib.dumps({'error': 'not_found'}),
                headers=[('Content-Type', 'application/json')],
            )

        data = self._build_status_json(fy)

        return request.make_response(
            json_lib.dumps(data),
            headers=[('Content-Type', 'application/json')],
        )

# -*- coding: utf-8 -*-

from odoo import models, fields, api
from odoo.exceptions import ValidationError
from datetime import datetime, timedelta, date
from dateutil.relativedelta import relativedelta
import uuid

class account_fiscal_year(models.Model):
    _inherit = 'account.fiscal.year'

    is_current = fields.Boolean(string='Current Year')
    is_plan = fields.Boolean(string='In Planning Stage')

    # Public access fields for program tree view
    public_access_token = fields.Char(string='Public Access Token', copy=False, index=True,
                                       help='Token unik untuk akses publik tree program kerja.')
    public_access_pin = fields.Char(string='PIN Akses Publik', copy=False,
                                     help='PIN yang harus dimasukkan untuk melihat tree program kerja.')
    public_url = fields.Char(string='Public URL', compute='_compute_public_url',
                              help='URL publik untuk melihat tree program kerja.')
    has_public_access_token = fields.Boolean(string='Has Public Token', compute='_compute_has_public_access_token')

    @api.depends('public_access_token')
    def _compute_has_public_access_token(self):
        for rec in self:
            rec.has_public_access_token = bool(rec.public_access_token)

    public_status_url = fields.Char(string='Public Status URL', compute='_compute_public_url',
                                      help='URL publik untuk melihat status program kerja (tanpa nominal).')
    public_status_active = fields.Boolean(string='Status Publik Aktif', default=True,
                                           help='Centang untuk mengaktifkan akses publik halaman status program. '
                                                'Jika tidak dicentang, link status publik akan dinonaktifkan.')

    @api.depends('public_access_token')
    def _compute_public_url(self):
        base_url = self.env['ir.config_parameter'].sudo().get_param('web.base.url')
        for rec in self:
            if rec.public_access_token:
                rec.public_url = '%s/program-kerja/%s' % (base_url, rec.public_access_token)
                rec.public_status_url = '%s/program-status/%s' % (base_url, rec.public_access_token)
            else:
                rec.public_url = False
                rec.public_status_url = False

    def action_generate_public_link(self):
        """Generate public access token and PIN for program tree view."""
        import random
        for rec in self:
            if not rec.public_access_token:
                rec.public_access_token = str(uuid.uuid4())
            if not rec.public_access_pin:
                rec.public_access_pin = '%06d' % random.randint(0, 999999)
        return True

    def action_regenerate_public_pin(self):
        """Regenerate PIN for public program tree access."""
        import random
        for rec in self:
            rec.public_access_pin = '%06d' % random.randint(0, 999999)
        return True

    def action_open_public_url(self):
        """Open public program tree URL in new tab."""
        self.ensure_one()
        if not self.public_access_token:
            self.action_generate_public_link()
        return {
            'type': 'ir.actions.act_url',
            'url': self.public_url,
            'target': 'new',
        }

    program_ids = fields.One2many(comodel_name='cms.program', inverse_name='fiscalyear_id', string='Program Kerja')
    period_ids = fields.One2many(comodel_name='account.period', inverse_name='fiscalyear_id', string='Periode')

    komisi_year_ids = fields.One2many(comodel_name='komisi.year', inverse_name='fiscalyear_id', string='Tahun Program Komisi')

    visi_id = fields.Many2one(comodel_name='cms.visi', string='Visi')

    _order = "name"

    def action_is_current(self):
        for rec in self:
            others = self.env["account.fiscal.year"].search([("id","!=",rec.id)])
            others.is_current = False
            rec.is_current = True

    def action_is_plan(self):
        for rec in self:
            others = self.env["account.fiscal.year"].search([("id","!=",rec.id)])
            others.is_plan = False
            rec.is_plan = True

    def action_confirm_all_programs(self):
        for rec in self:
            draft_programs = rec.program_ids.filtered(lambda p: p.state == 'draft')
            for program in draft_programs:
                program.state = 'confirmed'
                program.message_post(
                    body="Terkonfirmasi massal dari Tahun Pelayanan, menunggu validasi Tim RKA",
                    message_type='notification',
                    subtype_xmlid='mail.mt_note',
                )
                draft_lines = program.line_ids.filtered(lambda l: l.state == 'draft')
                draft_lines.write({'state': 'confirmed'})

    def action_recalculate_programs(self):
        """Force recompute all program line subtotals and program totals."""
        for rec in self:
            all_lines = rec.program_ids.mapped('line_ids')
            if all_lines:
                all_lines._calculate_subtotal()
            for program in rec.program_ids:
                program._calculate_total()

    def action_confirm_all_komisi_years(self):
        """Batch confirm all komisi.year records for this fiscal year."""
        for rec in self:
            for ky in rec.komisi_year_ids:
                if ky.state != 'confirmed':
                    ky.state = 'confirmed'

    def action_init_programs_from_current_year(self):
        for rec in self:
            if not rec.is_plan:
                continue
            current_year = self.env["account.fiscal.year"].search([("is_current", "=", True)], limit=1)
            if not current_year:
                raise ValidationError("Tidak ada tahun pelayanan yang aktif (Current Year). Silakan set tahun berjalan terlebih dahulu.")
            if current_year.id == rec.id:
                raise ValidationError("Tahun pelayanan yang sedang direncanakan tidak boleh sama dengan tahun berjalan.")
            for program in current_year.program_ids:
                # Skip if program with same code already exists in planning year
                existing = rec.program_ids.filtered(lambda p: p.code == program.code)
                if existing:
                    continue
                new_program = program.copy(default={
                    'fiscalyear_id': rec.id,
                    'state': 'draft',
                    'existing_program_ids': [(6, 0, [program.id])],
                })
                # Reset line states to draft
                new_program.line_ids.write({'state': 'draft'})

    def write(self, vals):
        result = super(account_fiscal_year, self).write(vals)

        for rec in self:
            if "is_current" in vals and vals["is_current"]:
                others = self.env["account.fiscal.year"].search([("id","!=",rec.id)])
                others.is_current = False
            if "is_plan" in vals and vals["is_plan"]:
                others = self.env["account.fiscal.year"].search([("id","!=",rec.id)])
                others.is_plan = False

        return result

    def action_generate_periods(self):
        for rec in self:
            for n in range(13):
                if n == 0:
                    date_from = datetime.strptime(str(rec.date_from), '%Y-%m-%d').date()
                    date_to = date_from
                else:
                    date_from = datetime.strptime(str(rec.date_from), '%Y-%m-%d').date() + relativedelta(months=n-1)
                    date_to = date_from + relativedelta(months=1) - relativedelta(days=1)
                period_name = date_from.strftime("%Y/%m") + ":" + str(n).zfill(2)
                period_data = {
                    "name" : period_name,
                    "date_from" : date_from,
                    "date_to" : date_to,
                    "fiscalyear_id" : rec.id,
                }
                periods = self.env["account.period"].search([("name","=",period_data["name"])])
                if len(periods) == 0:
                    self.env["account.period"].create(period_data)

    def action_summarize(self):
        """Summarize komisi.year records for this fiscal year."""
        komisis = self.env["cms.komisi"].search([])
        KomisiYear = self.env["komisi.year"].sudo()
        for komisi in komisis:
            komisi_years = KomisiYear.search([
                ("komisi_id", "=", komisi.id),
                ("fiscalyear_id", "=", self.id),
            ])
            name = (komisi.code or '') + ":" + (komisi.name or '') + ":" + (self.name or '')
            if not komisi_years:
                try:
                    komisi_year = KomisiYear.create({
                        "komisi_id": komisi.id,
                        "fiscalyear_id": self.id,
                        "name": name,
                    })
                    komisi_year.action_summarize()
                except Exception:
                    # Unique constraint violation - record was created concurrently
                    self.env.cr.rollback()
                    komisi_years = KomisiYear.search([
                        ("komisi_id", "=", komisi.id),
                        ("fiscalyear_id", "=", self.id),
                    ])
                    if komisi_years:
                        komisi_years[0].write({"name": name})
                        komisi_years[0].action_summarize()
            else:
                komisi_years[0].write({"name": name})
                komisi_years[0].action_summarize()


    def action_summarize_period_program_line(self):
        bidangs = self.env["cms.bidang"].search([])
        for bidang in bidangs:
            bidang.action_budget_month_line_summarize()

        for rec in self:
            for period in rec.period_ids:
                existing_account_period_program_lines = self.env["account.period.program.line"].search([("period_id","=",period.id)])
                existing_account_period_program_lines.unlink()
                print(period.name)
                pstr = period.name.split(":")[1]
                print(pstr)
                if int(pstr) == 0:
                    continue
                ipstr = int(pstr)
                amount_field_name = 'amount_budget_month_' + str(ipstr)
                print(amount_field_name)
                for program in rec.program_ids:
                    print(program.name)
                    for line in program.line_ids:
                        print(" ", line.name, line.amount_budget_month_1, line.amount_budget_month_2)
                        amount_field = getattr(line, amount_field_name)
                        print(amount_field)
                        data = {
                            "period_id" : period.id,
                            "program_line_id" : line.id,
                            "amount_rab" : 0,
                            "amount_rap" : 0,
                            "amount_total" : 0,
                        }
                        if amount_field < 0:
                            data["amount_rab"] = 0
                            data["amount_rap"] = -amount_field
                        if amount_field > 0:
                            data["amount_rab"] = amount_field
                            data["amount_rap"] = 0
                        data["amount_total"] = data["amount_rap"] - data["amount_rab"]
                        print(data)
                        if amount_field == 0:
                            continue
                        self.env["account.period.program.line"].create(data)

