    overflow: hidden;
}

.pcal-hero::before {
    content: '';
    position: absolute;
    width: 340px; height: 340px;
    border-radius: 50%;
    background: radial-gradient(circle, rgba(167,139,250,.18) 0%, transparent 70%);
    top: -80px; right: -60px;
    pointer-events: none;
}

.pcal-hero-content { position: relative; z-index: 1; }

.pcal-hero-icon {
    display: inline-flex;
    align-items: center; justify-content: center;
    width: 52px; height: 52px;
    border-radius: 14px;
    background: rgba(255,255,255,.12);
    backdrop-filter: blur(8px);
    font-size: 22px;
    margin-bottom: 14px;
    color: #e0e7ff;
}

.pcal-hero-title {
    font-size: 28px;
    font-weight: 700;
    margin: 0 0 6px;
    color: #fff;
    letter-spacing: -.3px;
}

.pcal-hero-sub {
    font-size: 15px;
