    to { transform: rotate(360deg); }
}

/* ---------- Empty State ---------- */
.pcal-empty {
    text-align: center;
    padding: 48px 24px;
    color: var(--pcal-text-muted);
}

.pcal-empty i {
    font-size: 48px;
    margin-bottom: 16px;
    color: rgba(99,102,241,.3);
}

.pcal-empty h3 {
    font-size: 18px;
    color: var(--pcal-text);
    margin: 0 0 8px;
}

