                        <p class="pcal-hero-sub"><t t-esc="company.name"/> — <t t-esc="fiscalyear.name"/></p>
                    </div>
                </div>

                <!-- Main Content -->
                <div class="pcal-wrap">

                    <!-- Toolbar -->
                    <div class="pcal-toolbar">
                        <div class="pcal-nav">
                            <button class="pcal-nav-btn" id="pcalPrevMonth" title="Bulan sebelumnya">
                                <i class="fa fa-chevron-left"/>
                            </button>
                            <span class="pcal-month-label" id="pcalMonthLabel">—</span>
                            <button class="pcal-nav-btn" id="pcalNextMonth" title="Bulan berikutnya">
                                <i class="fa fa-chevron-right"/>
                            </button>
                        </div>
                        <button class="pcal-today-btn" id="pcalToday">Hari Ini</button>
                    </div>

                    <!-- Filters -->
                    <div class="pcal-filters">
                        <select class="pcal-filter-select" id="pcalFilterBidang">
                            <option value="">Semua Bidang</option>
                            <t t-foreach="bidang_list" t-as="bid" t-key="bid.id">
                                <option t-att-value="bid.id"><t t-esc="bid.name"/></option>
                            </t>
                        </select>
                        <select class="pcal-filter-select" id="pcalFilterKomisi">
                            <option value="">Semua Komisi</option>
                            <t t-foreach="komisi_list" t-as="kom" t-key="kom.id">
                                <option t-att-value="kom.id"><t t-esc="kom.name"/></option>
                            </t>
                        </select>
                    </div>

                    <!-- Calendar Grid -->
                    <div class="pcal-grid-wrap">
                        <div class="pcal-grid" id="pcalGrid">
                            <!-- Rendered by JS -->
                        </div>
                    </div>

                    <!-- Legend -->
                    <div class="pcal-legend" id="pcalLegend">
                        <!-- Populated by JS from bidang colors -->
                    </div>

                    <!-- Upcoming Events -->
                    <div class="pcal-upcoming" id="pcalUpcoming">
                        <div class="pcal-upcoming-title">
                            <i class="fa fa-clock-o"/>
                            <span>Kegiatan Mendatang</span>
                        </div>
                        <div id="pcalUpcomingList">
                            <!-- Populated by JS -->
                        </div>
                    </div>

                </div>

                <!-- Footer -->
                <div class="pcal-footer">
                    <div class="pcal-wrap">
                        <p>© <t t-esc="fiscalyear.name"/> <t t-esc="company.name"/></p>
                    </div>
                </div>

                <!-- Event Detail Modal -->
                <div class="pcal-modal-overlay" id="pcalModal">
                    <div class="pcal-modal">
                        <button class="pcal-modal-close" id="pcalModalClose">
                            <i class="fa fa-times"/>
                        </button>
                        <h3 class="pcal-modal-title" id="pcalModalTitle">—</h3>
                        <div class="pcal-modal-meta" id="pcalModalMeta"></div>
                        <div class="pcal-modal-programs" id="pcalModalPrograms" style="display:none;"></div>
                    </div>
                </div>

                <!-- Day Detail Bottom Sheet (mobile) -->
                <div class="pcal-day-detail-overlay" id="pcalDayDetail">
                    <div class="pcal-day-detail-sheet">
                        <button class="pcal-modal-close" id="pcalDayDetailClose" style="float:right;">
                            <i class="fa fa-times"/>
                        </button>
                        <h3 class="pcal-day-detail-title" id="pcalDayDetailTitle">—</h3>
                        <div id="pcalDayDetailList"></div>
                    </div>
                </div>

                <!-- Calendar JS -->
                <script type="text/javascript">
                (function() {
                    'use strict';

                    var MONTH_NAMES = [
                        'Januari','Februari','Maret','April','Mei','Juni',
                        'Juli','Agustus','September','Oktober','November','Desember'
                    ];
                    var DAY_NAMES = ['Sen','Sel','Rab','Kam','Jum','Sab','Min'];
                    var MAX_CHIPS = 3;

                    var root = document.querySelector('.pcal');
                    var token = root.dataset.token;
                    var currentYear = parseInt(root.dataset.initYear);
                    var currentMonth = parseInt(root.dataset.initMonth);

                    var cachedEvents = [];
                    var allEvents = [];

                    // Elements
                    var grid = document.getElementById('pcalGrid');
                    var monthLabel = document.getElementById('pcalMonthLabel');
                    var legend = document.getElementById('pcalLegend');
                    var upcomingList = document.getElementById('pcalUpcomingList');
                    var modal = document.getElementById('pcalModal');
                    var modalTitle = document.getElementById('pcalModalTitle');
                    var modalMeta = document.getElementById('pcalModalMeta');
                    var modalPrograms = document.getElementById('pcalModalPrograms');
                    var dayDetail = document.getElementById('pcalDayDetail');
                    var dayDetailTitle = document.getElementById('pcalDayDetailTitle');
                    var dayDetailList = document.getElementById('pcalDayDetailList');

                    function pad(n) { return n &lt; 10 ? '0' + n : '' + n; }

                    function formatDate(dateStr) {
                        if (!dateStr) return '';
                        var d = new Date(dateStr);
                        return d.getDate() + ' ' + MONTH_NAMES[d.getMonth()] + ' ' + d.getFullYear();
                    }

                    function formatTime(dateStr) {
                        if (!dateStr) return '';
                        var d = new Date(dateStr);
                        return pad(d.getHours()) + ':' + pad(d.getMinutes());
                    }

                    function isSameDay(d1, d2) {
                        return d1.getFullYear() === d2.getFullYear() &amp;&amp;
                               d1.getMonth() === d2.getMonth() &amp;&amp;
                               d1.getDate() === d2.getDate();
                    }

                    function fetchEvents() {
                        var bidangId = document.getElementById('pcalFilterBidang').value;
                        var komisiId = document.getElementById('pcalFilterKomisi').value;

                        var url = '/kalender/' + token + '/events?year=' + currentYear + '&amp;month=' + currentMonth;
                        if (bidangId) url += '&amp;bidang_id=' + bidangId;
                        if (komisiId) url += '&amp;komisi_id=' + komisiId;

                        // Show loading
                        grid.innerHTML = '<div class="pcal-loading" style="grid-column:1/-1;"><div class="pcal-spinner"></div><span>Memuat...</span></div>';

                        fetch(url)
                            .then(function(r) { return r.json(); })
                            .then(function(data) {
                                if (data.error) {
                                    grid.innerHTML = '<div class="pcal-empty" style="grid-column:1/-1;"><i class="fa fa-exclamation-triangle"></i><p>Terjadi kesalahan.</p></div>';
                                    return;
                                }
                                allEvents = data.events || [];
                                renderCalendar(data);
                                renderLegend(data.events || []);
                                renderUpcoming(data.events || []);
                            })
                            .catch(function(err) {
                                console.error('Calendar fetch error:', err);
                                grid.innerHTML = '<div class="pcal-empty" style="grid-column:1/-1;"><i class="fa fa-exclamation-triangle"></i><p>Gagal memuat data kalender.</p></div>';
                            });
                    }

                    function renderCalendar(data) {
                        var events = data.events || [];

                        // Build date map
                        var eventsByDate = {};
                        events.forEach(function(ev) {
                            var start = new Date(ev.date_begin + 'T00:00:00');
                            var end = new Date(ev.date_end + 'T00:00:00');
                            for (var d = new Date(start); d &lt;= end; d.setDate(d.getDate() + 1)) {
                                var key = d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate());
                                if (!eventsByDate[key]) eventsByDate[key] = [];
                                eventsByDate[key].push(ev);
                            }
                        });

                        // Calendar range
                        var firstDay = new Date(currentYear, currentMonth - 1, 1);
                        var lastDay = new Date(currentYear, currentMonth, 0);
                        var startWeekday = firstDay.getDay(); // 0=Sun
                        // Shift to Monday-start: Mon=0 .. Sun=6
                        var startOffset = (startWeekday + 6) % 7;

                        var calStart = new Date(firstDay);
                        calStart.setDate(calStart.getDate() - startOffset);

                        var endWeekday = lastDay.getDay();
                        var endOffset = (7 - endWeekday) % 7;
                        // Ensure we have Mon-Sun, so endOffset based on Sunday
                        endOffset = endWeekday === 0 ? 0 : 7 - endWeekday;
                        var calEnd = new Date(lastDay);
                        calEnd.setDate(calEnd.getDate() + endOffset);

                        // Recalculate for Mon-start
                        calStart = new Date(firstDay);
                        startOffset = (firstDay.getDay() + 6) % 7;
                        calStart.setDate(calStart.getDate() - startOffset);

                        calEnd = new Date(lastDay);
                        var lastEndOffset = (7 - ((lastDay.getDay() + 6) % 7) - 1) % 7;
                        if (lastDay.getDay() !== 0) {
                            calEnd.setDate(calEnd.getDate() + (7 - lastDay.getDay()));
                        }

                        var today = new Date();
                        today.setHours(0,0,0,0);

                        var html = '';

                        // Day-of-week headers (Mon-Sun)
                        DAY_NAMES.forEach(function(dn, i) {
                            var cls = 'pcal-dow';
                            if (i === 6) cls += ' pcal-dow-sun';
                            html += '<div class="' + cls + '">' + dn + '</div>';
                        });

                        // Day cells
                        var d = new Date(calStart);
                        while (d &lt;= calEnd) {
                            var key = d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate());
                            var isCurrentMonth = d.getMonth() === (currentMonth - 1) &amp;&amp; d.getFullYear() === currentYear;
                            var isToday = isSameDay(d, today);
                            var isSunday = d.getDay() === 0;

                            var cellCls = 'pcal-day';
                            if (!isCurrentMonth) cellCls += ' pcal-day-other';
                            if (isToday) cellCls += ' pcal-day-today';
                            if (isSunday) cellCls += ' pcal-day-sun';

                            var dayEvents = eventsByDate[key] || [];

                            html += '<div class="' + cellCls + '" data-date="' + key + '" onclick="window._pcalDayClick(\'' + key + '\')">';
                            html += '<div class="pcal-day-num">' + d.getDate() + '</div>';
                            html += '<div class="pcal-events">';

                            var shown = Math.min(dayEvents.length, MAX_CHIPS);
                            for (var i = 0; i &lt; shown; i++) {
                                var ev = dayEvents[i];
                                var bg = ev.bidang_bg_color || '#6366f1';
                                var fg = ev.bidang_fg_color || '#fff';
                                html += '<div class="pcal-event-chip" style="background:' + bg + '22; color:' + fg + ';" onclick="event.stopPropagation(); window._pcalShowEvent(' + ev.id + ');">';
                                html += '<span class="pcal-event-chip-dot" style="background:' + bg + ';"></span>';
                                html += '<span class="pcal-event-chip-text">' + escapeHtml(ev.name) + '</span>';
                                html += '</div>';
                            }

                            if (dayEvents.length > MAX_CHIPS) {
                                html += '<div class="pcal-more-badge">+' + (dayEvents.length - MAX_CHIPS) + ' lainnya</div>';
                            }

                            html += '</div></div>';

                            d.setDate(d.getDate() + 1);
                        }

                        grid.innerHTML = html;

                        // Update month label
                        monthLabel.textContent = MONTH_NAMES[currentMonth - 1] + ' ' + currentYear;
                    }

                    function renderLegend(events) {
                        var bidangMap = {};
                        events.forEach(function(ev) {
                            if (ev.bidang_id &amp;&amp; !bidangMap[ev.bidang_id]) {
                                bidangMap[ev.bidang_id] = {
                                    name: ev.bidang_name,
                                    color: ev.bidang_bg_color || '#6366f1'
                                };
                            }
                        });
                        var html = '';
                        Object.keys(bidangMap).forEach(function(id) {
                            var b = bidangMap[id];
                            html += '<div class="pcal-legend-item">';
                            html += '<span class="pcal-legend-dot" style="background:' + b.color + ';"></span>';
                            html += '<span>' + escapeHtml(b.name) + '</span>';
                            html += '</div>';
                        });
                        legend.innerHTML = html;
                    }

                    function renderUpcoming(events) {
                        var today = new Date();
                        today.setHours(0,0,0,0);

                        var upcoming = events.filter(function(ev) {
                            var start = new Date(ev.date_begin + 'T00:00:00');
                            return start >= today;
                        }).sort(function(a, b) {
                            return new Date(a.date_begin) - new Date(b.date_begin);
                        }).slice(0, 5);

                        if (upcoming.length === 0) {
                            upcomingList.innerHTML = '<div class="pcal-empty" style="padding:16px 0;"><p>Tidak ada kegiatan mendatang bulan ini.</p></div>';
                            return;
                        }

                        var html = '';
                        upcoming.forEach(function(ev) {
                            var d = new Date(ev.date_begin + 'T00:00:00');
                            html += '<div class="pcal-upcoming-item" onclick="window._pcalShowEvent(' + ev.id + ')">';
                            html += '<div class="pcal-upcoming-date-box">';
                            html += '<div class="pcal-upcoming-date-day">' + d.getDate() + '</div>';
                            html += '<div class="pcal-upcoming-date-month">' + MONTH_NAMES[d.getMonth()].substring(0,3) + '</div>';
                            html += '</div>';
                            html += '<div>';
                            html += '<div class="pcal-upcoming-info-name">' + escapeHtml(ev.name) + '</div>';
                            html += '<div class="pcal-upcoming-info-meta">';
                            if (ev.komisi_name) html += '<i class="fa fa-users" style="margin-right:4px;"></i>' + escapeHtml(ev.komisi_name);
                            if (ev.location) html += ' · <i class="fa fa-map-marker" style="margin-right:2px;"></i>' + escapeHtml(ev.location);
                            html += '</div></div></div>';
                        });
                        upcomingList.innerHTML = html;
                    }

                    // Show event detail modal
                    window._pcalShowEvent = function(eventId) {
                        var ev = allEvents.find(function(e) { return e.id === eventId; });
                        if (!ev) return;

                        modalTitle.textContent = ev.name;

                        var metaHtml = '';

                        // Date
                        metaHtml += '<div class="pcal-modal-meta-row">';
                        metaHtml += '<div class="pcal-modal-meta-icon"><i class="fa fa-calendar"></i></div>';
                        metaHtml += '<div>' + formatDate(ev.date_begin);
                        if (ev.date_end &amp;&amp; ev.date_end !== ev.date_begin) {
                            metaHtml += ' — ' + formatDate(ev.date_end);
                        }
                        metaHtml += '</div></div>';

                        // Time
                        if (ev.date_begin_full) {
                            metaHtml += '<div class="pcal-modal-meta-row">';
                            metaHtml += '<div class="pcal-modal-meta-icon"><i class="fa fa-clock-o"></i></div>';
                            metaHtml += '<div>' + formatTime(ev.date_begin_full);
                            if (ev.date_end_full) {
                                metaHtml += ' - ' + formatTime(ev.date_end_full);
                            }
                            metaHtml += ' WIB</div></div>';
                        }

                        // Bidang
                        if (ev.bidang_name) {
                            metaHtml += '<div class="pcal-modal-meta-row">';
                            metaHtml += '<div class="pcal-modal-meta-icon"><i class="fa fa-tag"></i></div>';
                            metaHtml += '<div><span class="pcal-modal-badge" style="background:' + (ev.bidang_bg_color || '#6366f1') + '; color:' + (ev.bidang_fg_color || '#fff') + ';">' + escapeHtml(ev.bidang_name) + '</span></div>';
                            metaHtml += '</div>';
                        }

                        // Komisi
                        if (ev.komisi_name) {
                            metaHtml += '<div class="pcal-modal-meta-row">';
                            metaHtml += '<div class="pcal-modal-meta-icon"><i class="fa fa-users"></i></div>';
                            metaHtml += '<div>' + escapeHtml(ev.komisi_name) + '</div>';
                            metaHtml += '</div>';
                        }

                        // Location
                        if (ev.location) {
                            metaHtml += '<div class="pcal-modal-meta-row">';
                            metaHtml += '<div class="pcal-modal-meta-icon"><i class="fa fa-map-marker"></i></div>';
                            metaHtml += '<div>' + escapeHtml(ev.location) + '</div>';
                            metaHtml += '</div>';
                        }

                        // Stage
                        if (ev.stage) {
                            metaHtml += '<div class="pcal-modal-meta-row">';
                            metaHtml += '<div class="pcal-modal-meta-icon"><i class="fa fa-flag"></i></div>';
                            metaHtml += '<div>' + escapeHtml(ev.stage) + '</div>';
                            metaHtml += '</div>';
                        }

                        modalMeta.innerHTML = metaHtml;

                        // Programs
                        if (ev.programs &amp;&amp; ev.programs.length > 0) {
                            var progHtml = '<h4>Program Kerja Terkait</h4>';
                            ev.programs.forEach(function(p) {
                                progHtml += '<span class="pcal-prog-chip"><span class="pcal-prog-chip-code">' + escapeHtml(p.code) + '</span> ' + escapeHtml(p.name) + '</span>';
                            });
                            modalPrograms.innerHTML = progHtml;
                            modalPrograms.style.display = 'block';
                        } else {
                            modalPrograms.style.display = 'none';
                        }

                        modal.classList.add('pcal-show');
                    };

                    // Day click (show all events for that day)
                    window._pcalDayClick = function(dateKey) {
                        var dayEvents = allEvents.filter(function(ev) {
                            var start = new Date(ev.date_begin + 'T00:00:00');
                            var end = new Date(ev.date_end + 'T00:00:00');
                            var target = new Date(dateKey + 'T00:00:00');
                            return target >= start &amp;&amp; target &lt;= end;
                        });

                        if (dayEvents.length === 0) return;

                        // On wide screens, if only 1 event, show detail modal
                        if (dayEvents.length === 1 &amp;&amp; window.innerWidth >= 768) {
                            window._pcalShowEvent(dayEvents[0].id);
                            return;
                        }

                        var parts = dateKey.split('-');
                        var d = new Date(parseInt(parts[0]), parseInt(parts[1]) - 1, parseInt(parts[2]));
                        dayDetailTitle.textContent = d.getDate() + ' ' + MONTH_NAMES[d.getMonth()] + ' ' + d.getFullYear() + ' (' + dayEvents.length + ' kegiatan)';

                        var html = '';
                        dayEvents.forEach(function(ev) {
                            html += '<div class="pcal-day-detail-event" onclick="window._pcalShowEvent(' + ev.id + '); document.getElementById(\'pcalDayDetail\').classList.remove(\'pcal-show\');">';
                            html += '<div class="pcal-day-detail-dot" style="background:' + (ev.bidang_bg_color || '#6366f1') + ';"></div>';
                            html += '<div>';
                            html += '<div class="pcal-day-detail-event-name">' + escapeHtml(ev.name) + '</div>';
                            html += '<div class="pcal-day-detail-event-time">';
                            if (ev.komisi_name) html += escapeHtml(ev.komisi_name);
                            if (ev.date_begin_full) html += ' · ' + formatTime(ev.date_begin_full);
                            html += '</div></div></div>';
                        });
                        dayDetailList.innerHTML = html;
                        dayDetail.classList.add('pcal-show');
                    };

                    function escapeHtml(str) {
                        if (!str) return '';
                        return str.replace(/&amp;/g, '&amp;amp;')
                                  .replace(/&lt;/g, '&amp;lt;')
                                  .replace(/>/g, '&amp;gt;')
                                  .replace(/"/g, '&amp;quot;');
                    }

                    // Navigation
                    document.getElementById('pcalPrevMonth').addEventListener('click', function() {
                        currentMonth--;
                        if (currentMonth &lt; 1) { currentMonth = 12; currentYear--; }
                        fetchEvents();
                    });
                    document.getElementById('pcalNextMonth').addEventListener('click', function() {
                        currentMonth++;
                        if (currentMonth > 12) { currentMonth = 1; currentYear++; }
                        fetchEvents();
                    });
                    document.getElementById('pcalToday').addEventListener('click', function() {
                        var today = new Date();
                        currentYear = today.getFullYear();
                        currentMonth = today.getMonth() + 1;
                        fetchEvents();
                    });

                    // Filters
                    document.getElementById('pcalFilterBidang').addEventListener('change', fetchEvents);
                    document.getElementById('pcalFilterKomisi').addEventListener('change', fetchEvents);

                    // Modal close
                    document.getElementById('pcalModalClose').addEventListener('click', function() {
                        modal.classList.remove('pcal-show');
                    });
                    modal.addEventListener('click', function(e) {
                        if (e.target === modal) modal.classList.remove('pcal-show');
                    });

                    // Day detail close
                    document.getElementById('pcalDayDetailClose').addEventListener('click', function() {
                        dayDetail.classList.remove('pcal-show');
                    });
                    dayDetail.addEventListener('click', function(e) {
                        if (e.target === dayDetail) dayDetail.classList.remove('pcal-show');
                    });

                    // Keyboard: Escape closes modals, Arrow keys navigate months
                    document.addEventListener('keydown', function(e) {
                        if (e.key === 'Escape') {
                            modal.classList.remove('pcal-show');
                            dayDetail.classList.remove('pcal-show');
                        }
                        if (e.key === 'ArrowLeft' &amp;&amp; !e.ctrlKey &amp;&amp; !e.metaKey) {
                            if (!modal.classList.contains('pcal-show') &amp;&amp; !dayDetail.classList.contains('pcal-show')) {
                                currentMonth--;
                                if (currentMonth &lt; 1) { currentMonth = 12; currentYear--; }
                                fetchEvents();
                            }
                        }
                        if (e.key === 'ArrowRight' &amp;&amp; !e.ctrlKey &amp;&amp; !e.metaKey) {
                            if (!modal.classList.contains('pcal-show') &amp;&amp; !dayDetail.classList.contains('pcal-show')) {
                                currentMonth++;
                                if (currentMonth > 12) { currentMonth = 1; currentYear++; }
                                fetchEvents();
                            }
                        }
                    });

                    // Initial load
                    fetchEvents();

                })();
                </script>

            </div>
        </t>
    </template>

