/* ---------- Reset & Variables ---------- */
.pcal {
    --pcal-bg: #0f0e17;
    --pcal-surface: #1a1933;
    --pcal-surface-2: #242244;
    --pcal-border: rgba(255,255,255,.08);
    --pcal-text: #e2e0f0;
    --pcal-text-muted: #9894b8;
    --pcal-accent: #6366f1;
    --pcal-accent-glow: rgba(99,102,241,.25);
    --pcal-today-ring: #a78bfa;
    --pcal-radius: 14px;
    --pcal-radius-sm: 8px;
    --pcal-shadow: 0 4px 24px rgba(0,0,0,.35);

    font-family: 'Inter', 'Segoe UI', system-ui, -apple-system, sans-serif;
    background: var(--pcal-bg);
    color: var(--pcal-text);
    min-height: 100vh;
    line-height: 1.5;
    -webkit-font-smoothing: antialiased;
}

.pcal *,
.pcal *::before,
.pcal *::after { box-sizing: border-box; }

.pcal a { color: inherit; text-decoration: none; }

.pcal-wrap {
    max-width: 1140px;
    margin: 0 auto;
    padding: 0 20px;
}

/* ---------- Hero / Header ---------- */
.pcal-hero {
    background: linear-gradient(135deg, #312e81 0%, #4338ca 40%, #6366f1 100%);
    padding: 48px 0 36px;
    position: relative;
    overflow: hidden;
}

.pcal-hero::before {
    content: '';
    position: absolute;
    width: 340px; height: 340px;
    border-radius: 50%;
    background: radial-gradient(circle, rgba(167,139,250,.18) 0%, transparent 70%);
    top: -80px; right: -60px;
    pointer-events: none;
}

.pcal-hero-content { position: relative; z-index: 1; }

.pcal-hero-icon {
    display: inline-flex;
    align-items: center; justify-content: center;
    width: 52px; height: 52px;
    border-radius: 14px;
    background: rgba(255,255,255,.12);
    backdrop-filter: blur(8px);
    font-size: 22px;
    margin-bottom: 14px;
    color: #e0e7ff;
}

.pcal-hero-title {
    font-size: 28px;
    font-weight: 700;
    margin: 0 0 6px;
    color: #fff;
    letter-spacing: -.3px;
}

.pcal-hero-sub {
    font-size: 15px;
    color: rgba(255,255,255,.7);
    margin: 0;
}

/* ---------- Toolbar ---------- */
.pcal-toolbar {
    display: flex;
    align-items: center;
    justify-content: space-between;
    flex-wrap: wrap;
    gap: 12px;
    padding: 20px 0;
}

.pcal-nav {
    display: flex;
    align-items: center;
    gap: 8px;
}

.pcal-nav-btn {
    display: inline-flex;
    align-items: center; justify-content: center;
    width: 40px; height: 40px;
    border: 1px solid var(--pcal-border);
    border-radius: 10px;
    background: var(--pcal-surface);
    color: var(--pcal-text);
    cursor: pointer;
    font-size: 16px;
    transition: all .2s;
}
.pcal-nav-btn:hover {
    background: var(--pcal-accent);
    border-color: var(--pcal-accent);
    color: #fff;
    box-shadow: 0 0 14px var(--pcal-accent-glow);
}

.pcal-month-label {
    font-size: 20px;
