}
.pcal-today-btn:hover {
    background: var(--pcal-accent);
    border-color: var(--pcal-accent);
    color: #fff;
}

/* ---------- Filters ---------- */
.pcal-filters {
    display: flex;
    gap: 10px;
    flex-wrap: wrap;
    margin-bottom: 12px;
}

.pcal-filter-select {
    padding: 8px 14px;
    border-radius: 10px;
    border: 1px solid var(--pcal-border);
    background: var(--pcal-surface);
    color: var(--pcal-text);
    font-size: 13px;
    font-family: inherit;
    appearance: none;
    -webkit-appearance: none;
    background-image: url("data:image/svg+xml,%3Csvg width='10' height='6' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M0 0l5 6 5-6z' fill='%239894b8'/%3E%3C/svg%3E");
