    font-weight: 700;
    padding: 2px 0;
    cursor: pointer;
}
.pcal-more-badge:hover { text-decoration: underline; }

/* ---------- Event Detail Modal / Drawer ---------- */
.pcal-modal-overlay {
    position: fixed;
    inset: 0;
    background: rgba(0,0,0,.6);
    backdrop-filter: blur(4px);
    z-index: 9999;
    display: flex;
    align-items: center;
