    def action_generate_periods(self):
        for rec in self:
            for n in range(13):
                if n == 0:
                    date_from = datetime.strptime(str(rec.date_from), '%Y-%m-%d').date()
                    date_to = date_from
                else:
                    date_from = datetime.strptime(str(rec.date_from), '%Y-%m-%d').date() + relativedelta(months=n-1)
