            }
        )

    @http.route('/kalender/<string:token>/events', type='http', auth='public',
                website=True, csrf=False)
    def public_calendar_events_api(self, token, **kwargs):
        """JSON API endpoint returning events for a given month/year."""
        fy = self._get_fiscalyear_by_token(token)
        if not fy or not fy.public_calendar_active:
            return request.make_response(
                json.dumps({'error': 'not_found'}),
                headers=[('Content-Type', 'application/json')],
            )

        try:
            year = int(kwargs.get('year', date.today().year))
            month = int(kwargs.get('month', date.today().month))
        except (ValueError, TypeError):
            year = date.today().year
            month = date.today().month

        if not (1 <= month <= 12):
            month = date.today().month

        # Calculate date range for the month (with padding for calendar grid)
        first_day = date(year, month, 1)
        if month == 12:
            last_day = date(year + 1, 1, 1) - timedelta(days=1)
        else:
            last_day = date(year, month + 1, 1) - timedelta(days=1)

        # Extend range to cover full calendar weeks (Mon-Sun)
        start_weekday = first_day.weekday()  # 0=Mon
        cal_start = first_day - timedelta(days=start_weekday)
        end_weekday = last_day.weekday()
        cal_end = last_day + timedelta(days=(6 - end_weekday))

        # Build domain for events that overlap with the calendar range
        domain = [
            ('date_begin', '<=', datetime.combine(cal_end, datetime.max.time())),
            ('date_end', '>=', datetime.combine(cal_start, datetime.min.time())),
        ]

        # Optional filters
        bidang_id = kwargs.get('bidang_id')
        komisi_id = kwargs.get('komisi_id')
        if bidang_id:
            try:
                domain.append(('bidang_id', '=', int(bidang_id)))
            except (ValueError, TypeError):
                pass
        if komisi_id:
            try:
                domain.append(('komisi_id', '=', int(komisi_id)))
            except (ValueError, TypeError):
                pass

        events = request.env['event.event'].sudo().search(domain, order='date_begin asc')

        can_manage = self._can_manage_events()

        event_list = []
        for ev in events:
            programs = []
            for prog in ev.related_program_ids:
                programs.append({
                    'id': prog.id,
                    'code': prog.code or '',
                    'name': prog.name or '',
                })

            event_list.append({
                'id': ev.id,
                'name': ev.name or '',
                'date_begin': ev.date_begin.strftime('%Y-%m-%d') if ev.date_begin else '',
                'date_end': ev.date_end.strftime('%Y-%m-%d') if ev.date_end else '',
                'date_begin_full': ev.date_begin.strftime('%Y-%m-%dT%H:%M:%S') if ev.date_begin else '',
                'date_end_full': ev.date_end.strftime('%Y-%m-%dT%H:%M:%S') if ev.date_end else '',
                'bidang_id': ev.bidang_id.id if ev.bidang_id else False,
                'bidang_name': ev.bidang_id.name if ev.bidang_id else '',
                'bidang_code': ev.bidang_id.code if ev.bidang_id else '',
                'bidang_bg_color': ev.bidang_id.bg_color if ev.bidang_id else '#6366f1',
                'bidang_fg_color': ev.bidang_id.fg_color if ev.bidang_id else '#ffffff',
                'komisi_id': ev.komisi_id.id if ev.komisi_id else False,
                'komisi_name': ev.komisi_id.name if ev.komisi_id else '',
                'komisi_code': ev.komisi_id.code if ev.komisi_id else '',
                'stage': ev.stage_id.name if ev.stage_id else '',
                'description': ev.description or '',
                'programs': programs,
                'location': ev.address_id.name if ev.address_id else '',
            })

        result = {
            'year': year,
            'month': month,
            'cal_start': cal_start.strftime('%Y-%m-%d'),
            'cal_end': cal_end.strftime('%Y-%m-%d'),
            'events': event_list,
            'can_manage': can_manage,
        }

        return request.make_response(
            json.dumps(result),
            headers=[('Content-Type', 'application/json')],
        )

    # ================================================================
    # CRUD Endpoints (authenticated users only)
    # ================================================================

    def _json_error(self, msg, status=400):
        return request.make_response(
            json.dumps({'error': msg}),
            headers=[('Content-Type', 'application/json')],
            status=status,
        )

    def _json_ok(self, data=None):
        return request.make_response(
            json.dumps({'ok': True, **(data or {})}),
            headers=[('Content-Type', 'application/json')],
        )

    def _parse_event_json(self):
        """Parse JSON body for create/update."""
        try:
            body = json.loads(request.httprequest.data)
        except (json.JSONDecodeError, TypeError):
            return None
        return body

    @http.route('/kalender/<string:token>/event/create', type='http',
                auth='public', website=True, csrf=False, methods=['POST'])
    def calendar_event_create(self, token, **kwargs):
        """Create one or more events (supports recurring)."""
        fy = self._get_fiscalyear_by_token(token)
        if not fy or not fy.public_calendar_active:
            return self._json_error('not_found', 404)

        if not self._can_manage_events():
            return self._json_error('unauthorized', 403)

        body = self._parse_event_json()
        if not body:
            return self._json_error('invalid_json')

        name = (body.get('name') or '').strip()
        if not name:
            return self._json_error('name_required')

        # Parse dates
        try:
            date_begin = datetime.strptime(body['date_begin'], '%Y-%m-%dT%H:%M')
            date_end = datetime.strptime(body['date_end'], '%Y-%m-%dT%H:%M')
        except (KeyError, ValueError, TypeError):
            return self._json_error('invalid_dates')

        if date_end < date_begin:
            date_end = date_begin

        # Optional fields
        komisi_id = body.get('komisi_id')
        program_ids = body.get('program_ids', [])
        description = body.get('description', '')

        # Recurrence
        repeat_enabled = body.get('repeat_enabled', False)
        repeat_interval = body.get('repeat_interval', 'week')  # day, week, month
        repeat_count = body.get('repeat_count', 0)  # 0 means use repeat_until
        repeat_until = body.get('repeat_until', '')  # YYYY-MM-DD

        # Build base vals
        base_vals = {
            'name': name,
            'description': description,
            'date_tz': 'Asia/Jakarta',
        }

        if komisi_id:
            try:
                base_vals['komisi_id'] = int(komisi_id)
            except (ValueError, TypeError):
                pass

        if program_ids:
            valid_ids = []
            for pid in program_ids:
                try:
                    valid_ids.append(int(pid))
                except (ValueError, TypeError):
                    pass
            if valid_ids:
                base_vals['related_program_ids'] = [(6, 0, valid_ids)]

        Event = request.env['event.event'].sudo()
        created_ids = []

        # Generate date list
        dates = [(date_begin, date_end)]

        if repeat_enabled:
            duration = date_end - date_begin

            if repeat_interval == 'day':
                delta = timedelta(days=1)
            elif repeat_interval == 'week':
                delta = timedelta(weeks=1)
            elif repeat_interval == 'month':
                delta = None  # use relativedelta
            else:
                delta = timedelta(weeks=1)

            if repeat_count and int(repeat_count) > 0:
                count = min(int(repeat_count), 365)  # safety cap
                for i in range(1, count):
                    if repeat_interval == 'month':
                        new_begin = date_begin + relativedelta(months=i)
                    else:
                        new_begin = date_begin + (delta * i)
                    new_end = new_begin + duration
                    dates.append((new_begin, new_end))
            elif repeat_until:
                try:
                    until_date = datetime.strptime(repeat_until, '%Y-%m-%d')
                    until_date = until_date.replace(hour=23, minute=59, second=59)
                except (ValueError, TypeError):
                    until_date = date_begin + timedelta(days=365)

                i = 1
                while True:
                    if repeat_interval == 'month':
                        new_begin = date_begin + relativedelta(months=i)
                    else:
                        new_begin = date_begin + (delta * i)
                    if new_begin > until_date:
                        break
                    new_end = new_begin + duration
                    dates.append((new_begin, new_end))
                    i += 1
                    if i > 365:  # safety
                        break

        for (db, de) in dates:
            vals = dict(base_vals)
            vals['date_begin'] = db
            vals['date_end'] = de
            ev = Event.create(vals)
            created_ids.append(ev.id)

        _logger.info(
            "Calendar: user %s created %d event(s) '%s' via public calendar",
            request.env.user.login, len(created_ids), name,
        )

        return self._json_ok({'created_ids': created_ids, 'count': len(created_ids)})

    @http.route('/kalender/<string:token>/event/<int:event_id>/update', type='http',
                auth='public', website=True, csrf=False, methods=['POST'])
    def calendar_event_update(self, token, event_id, **kwargs):
        """Update an existing event."""
        fy = self._get_fiscalyear_by_token(token)
        if not fy or not fy.public_calendar_active:
            return self._json_error('not_found', 404)

        if not self._can_manage_events():
            return self._json_error('unauthorized', 403)

        body = self._parse_event_json()
        if not body:
            return self._json_error('invalid_json')

        event = request.env['event.event'].sudo().browse(event_id)
        if not event.exists():
            return self._json_error('event_not_found', 404)

        vals = {}

        name = body.get('name')
        if name is not None:
            name = name.strip()
            if not name:
                return self._json_error('name_required')
            vals['name'] = name

        # Dates
        if 'date_begin' in body:
            try:
                vals['date_begin'] = datetime.strptime(body['date_begin'], '%Y-%m-%dT%H:%M')
            except (ValueError, TypeError):
                return self._json_error('invalid_date_begin')
        if 'date_end' in body:
            try:
                vals['date_end'] = datetime.strptime(body['date_end'], '%Y-%m-%dT%H:%M')
            except (ValueError, TypeError):
                return self._json_error('invalid_date_end')

        if 'description' in body:
            vals['description'] = body['description'] or ''

        if 'komisi_id' in body:
            kid = body['komisi_id']
            try:
                vals['komisi_id'] = int(kid) if kid else False
            except (ValueError, TypeError):
                vals['komisi_id'] = False

        if 'program_ids' in body:
            valid_ids = []
            for pid in body['program_ids']:
                try:
                    valid_ids.append(int(pid))
                except (ValueError, TypeError):
                    pass
            vals['related_program_ids'] = [(6, 0, valid_ids)]

        if vals:
            event.write(vals)

        _logger.info(
            "Calendar: user %s updated event %d via public calendar",
            request.env.user.login, event_id,
        )

        return self._json_ok()

    @http.route('/kalender/<string:token>/event/<int:event_id>/delete', type='http',
                auth='public', website=True, csrf=False, methods=['POST'])
    def calendar_event_delete(self, token, event_id, **kwargs):
        """Delete an event."""
        fy = self._get_fiscalyear_by_token(token)
        if not fy or not fy.public_calendar_active:
            return self._json_error('not_found', 404)

        if not self._can_manage_events():
            return self._json_error('unauthorized', 403)

        event = request.env['event.event'].sudo().browse(event_id)
        if not event.exists():
            return self._json_error('event_not_found', 404)

        event_name = event.name
        event.unlink()

        _logger.info(
            "Calendar: user %s deleted event %d (%s) via public calendar",
            request.env.user.login, event_id, event_name,
        )

        return self._json_ok()
