        return {
            'bidang_options': [{'id': b.id, 'name': b.name, 'code': b.code or ''} for b in bidang_list],
            'komisi_options': [{'id': k.id, 'name': k.name, 'code': k.code or '',
                                'bidang_id': k.bidang_id.id if k.bidang_id else False} for k in komisi_list],
