/**
 * Public Calendar Management JS
 * Handles CRUD operations for authenticated users.
 * Loaded inline within the QWeb template.
 */
(function () {
  "use strict";

  var root = document.querySelector(".pcal");
  if (!root) return;

  var CAN_MANAGE = root.dataset.canManage === "1";
  var TOKEN = root.dataset.token;
  var PROGRAMS = [];
  try {
    PROGRAMS = JSON.parse(root.dataset.programs || "[]");
  } catch (e) {}

  if (!CAN_MANAGE) return;

  // ========== Toast ==========
  function toast(msg, type) {
    var el = document.createElement("div");
    el.className = "pcal-toast pcal-toast-" + (type || "success");
    el.textContent = msg;
    document.body.appendChild(el);
    requestAnimationFrame(function () {
      el.classList.add("pcal-show");
    });
    setTimeout(function () {
      el.classList.remove("pcal-show");
      setTimeout(function () {
        el.remove();
      }, 400);
    }, 3000);
  }

  // ========== API Helpers ==========
  function apiPost(url, body) {
    return fetch(url, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(body),
    }).then(function (r) {
      return r.json();
    });
  }

  // ========== FAB Button ==========
  var fab = document.createElement("button");
  fab.className = "pcal-fab";
  fab.title = "Buat Kegiatan Baru";
  fab.innerHTML = '<i class="fa fa-plus"></i>';
  fab.addEventListener("click", function () {
    openForm(null);
  });
  document.body.appendChild(fab);

  // ========== Form Modal ==========
  var formOverlay = document.getElementById("pcalFormModal");
  var formEl = document.getElementById("pcalEventForm");

  function closeForm() {
    formOverlay.classList.remove("pcal-show");
  }

  document
    .getElementById("pcalFormClose")
    .addEventListener("click", closeForm);
  formOverlay.addEventListener("click", function (e) {
    if (e.target === formOverlay) closeForm();
  });

  function openForm(ev, prefillDate) {
    var isEdit = !!ev;
    document.getElementById("pcalFormTitle").textContent = isEdit
      ? "Edit Kegiatan"
      : "Buat Kegiatan Baru";
    document.getElementById("pcalFormEventId").value = isEdit ? ev.id : "";

    document.getElementById("pcalFormName").value = isEdit ? ev.name : "";

    // Dates
    var now = new Date();
    var defDate = prefillDate || now.getFullYear() + "-" + pad(now.getMonth()+1) + "-" + pad(now.getDate());
    if (isEdit && ev.date_begin_full) {
      document.getElementById("pcalFormDateBegin").value =
        ev.date_begin_full.substring(0, 16);
    } else {
      document.getElementById("pcalFormDateBegin").value = defDate + "T08:00";
    }
    if (isEdit && ev.date_end_full) {
      document.getElementById("pcalFormDateEnd").value =
        ev.date_end_full.substring(0, 16);
    } else {
      document.getElementById("pcalFormDateEnd").value = defDate + "T10:00";
    }

    // Komisi
    document.getElementById("pcalFormKomisi").value =
      isEdit && ev.komisi_id ? ev.komisi_id : "";

    // Description
    document.getElementById("pcalFormDesc").value =
      isEdit ? (ev.description || "").replace(/<[^>]*>/g, "") : "";

    // Programs multi-select
    var progContainer = document.getElementById("pcalFormPrograms");
    var selectedProgramIds = [];
    if (isEdit && ev.programs) {
      selectedProgramIds = ev.programs.map(function (p) {
        return p.id;
      });
    }
    renderProgramChips(progContainer, selectedProgramIds);

    // Recurrence (only for create)
    var recSection = document.getElementById("pcalRecurrenceSection");
    if (isEdit) {
      recSection.style.display = "none";
    } else {
      recSection.style.display = "";
      document.getElementById("pcalRepeatCheck").checked = false;
      document.getElementById("pcalRecurrenceOpts").classList.remove("pcal-active");
      document.getElementById("pcalRepeatCount").value = "4";
      document.getElementById("pcalRepeatUntil").value = "";
    }
    setRepeatInterval("week");
    setRepeatEndMode("count");

    formOverlay.classList.add("pcal-show");
    setTimeout(function () {
      document.getElementById("pcalFormName").focus();
    }, 100);
  }

  function renderProgramChips(container, selectedIds) {
    var html = "";
    var komisiFilter = document.getElementById("pcalFormKomisi").value;
    var filtered = PROGRAMS;
    if (komisiFilter) {
      var kid = parseInt(komisiFilter);
      filtered = PROGRAMS.filter(function (p) {
        return !p.komisi_id || p.komisi_id === kid;
      });
    }
    filtered.forEach(function (p) {
      var sel = selectedIds.indexOf(p.id) !== -1 ? " pcal-selected" : "";
      html += '<span class="pcal-multi-chip' + sel + '" data-id="' + p.id + '">';
      html += escapeHtml(p.label || p.code + " " + p.name);
      html += "</span>";
    });
    container.innerHTML = html;

    // Click toggle
    container.querySelectorAll(".pcal-multi-chip").forEach(function (chip) {
      chip.addEventListener("click", function () {
        chip.classList.toggle("pcal-selected");
      });
    });
  }

  // Komisi change -> re-render programs
  document
    .getElementById("pcalFormKomisi")
    .addEventListener("change", function () {
      var sel = getSelectedProgramIds();
      renderProgramChips(document.getElementById("pcalFormPrograms"), sel);
    });

  function getSelectedProgramIds() {
    var ids = [];
    document
      .querySelectorAll("#pcalFormPrograms .pcal-multi-chip.pcal-selected")
      .forEach(function (el) {
        ids.push(parseInt(el.dataset.id));
      });
    return ids;
  }

  // Recurrence controls
  var _repeatInterval = "week";
  var _repeatEndMode = "count";

  function setRepeatInterval(val) {
    _repeatInterval = val;
    document
      .querySelectorAll("#pcalIntervalPills .pcal-radio-pill")
      .forEach(function (p) {
        p.classList.toggle("pcal-active", p.dataset.val === val);
      });
  }
  function setRepeatEndMode(val) {
    _repeatEndMode = val;
    document.querySelectorAll("#pcalEndModePills .pcal-repeat-mode-pill").forEach(function (p) {
      p.classList.toggle("pcal-active", p.dataset.val === val);
    });
    document.getElementById("pcalRepeatCountWrap").style.display =
      val === "count" ? "" : "none";
    document.getElementById("pcalRepeatUntilWrap").style.display =
      val === "until" ? "" : "none";
  }

  document.getElementById("pcalRepeatCheck").addEventListener("change", function () {
    document.getElementById("pcalRecurrenceOpts").classList.toggle("pcal-active", this.checked);
  });

  document.querySelectorAll("#pcalIntervalPills .pcal-radio-pill").forEach(function (p) {
    p.addEventListener("click", function () { setRepeatInterval(p.dataset.val); });
  });
  document.querySelectorAll("#pcalEndModePills .pcal-repeat-mode-pill").forEach(function (p) {
    p.addEventListener("click", function () { setRepeatEndMode(p.dataset.val); });
  });

  // Form submit
  formEl.addEventListener("submit", function (e) {
    e.preventDefault();
    var eventId = document.getElementById("pcalFormEventId").value;
    var isEdit = !!eventId;

    var body = {
      name: document.getElementById("pcalFormName").value.trim(),
      date_begin: document.getElementById("pcalFormDateBegin").value,
      date_end: document.getElementById("pcalFormDateEnd").value,
      komisi_id: document.getElementById("pcalFormKomisi").value || null,
      description: document.getElementById("pcalFormDesc").value,
      program_ids: getSelectedProgramIds(),
    };

    if (!body.name) {
      toast("Nama kegiatan wajib diisi", "error");
      return;
    }

    // Recurrence (create only)
    if (!isEdit && document.getElementById("pcalRepeatCheck").checked) {
      body.repeat_enabled = true;
      body.repeat_interval = _repeatInterval;
      if (_repeatEndMode === "count") {
        body.repeat_count = parseInt(document.getElementById("pcalRepeatCount").value) || 4;
      } else {
        body.repeat_until = document.getElementById("pcalRepeatUntil").value;
      }
    }

    var url = isEdit
      ? "/kalender/" + TOKEN + "/event/" + eventId + "/update"
      : "/kalender/" + TOKEN + "/event/create";

    var submitBtn = document.getElementById("pcalFormSubmit");
    submitBtn.disabled = true;
    submitBtn.textContent = "Menyimpan...";

    apiPost(url, body)
      .then(function (data) {
        submitBtn.disabled = false;
        submitBtn.textContent = "Simpan";
        if (data.error) {
          toast("Gagal: " + data.error, "error");
          return;
        }
        closeForm();
        var msg = isEdit ? "Kegiatan diperbarui" : "Kegiatan dibuat";
        if (data.count && data.count > 1)
          msg += " (" + data.count + " event berulang)";
        toast(msg, "success");
        // Refresh calendar
        if (typeof window._pcalRefresh === "function") window._pcalRefresh();
      })
      .catch(function () {
        submitBtn.disabled = false;
        submitBtn.textContent = "Simpan";
        toast("Terjadi kesalahan jaringan", "error");
      });
  });

  // ========== Edit & Delete from Detail Modal ==========
  window._pcalEditEvent = function (eventId) {
    var ev =
      window._pcalAllEvents &&
      window._pcalAllEvents.find(function (e) {
        return e.id === eventId;
      });
    if (!ev) return;
    document.getElementById("pcalModal").classList.remove("pcal-show");
    openForm(ev);
  };

  window._pcalDeleteEvent = function (eventId) {
    var ev =
      window._pcalAllEvents &&
      window._pcalAllEvents.find(function (e) {
        return e.id === eventId;
      });
    if (!ev) return;
    document.getElementById("pcalModal").classList.remove("pcal-show");

    // Show confirm dialog
    var confirmOverlay = document.getElementById("pcalConfirmModal");
    document.getElementById("pcalConfirmName").textContent = ev.name;
    confirmOverlay.dataset.eventId = eventId;
    confirmOverlay.classList.add("pcal-show");
  };

  // Confirm delete
  document.getElementById("pcalConfirmDelete").addEventListener("click", function () {
    var confirmOverlay = document.getElementById("pcalConfirmModal");
    var eventId = confirmOverlay.dataset.eventId;
    confirmOverlay.classList.remove("pcal-show");

    apiPost("/kalender/" + TOKEN + "/event/" + eventId + "/delete", {})
      .then(function (data) {
        if (data.error) {
          toast("Gagal menghapus: " + data.error, "error");
          return;
        }
        toast("Kegiatan dihapus", "success");
        if (typeof window._pcalRefresh === "function") window._pcalRefresh();
      })
      .catch(function () {
        toast("Terjadi kesalahan jaringan", "error");
      });
  });

  document.getElementById("pcalConfirmCancel").addEventListener("click", function () {
    document.getElementById("pcalConfirmModal").classList.remove("pcal-show");
  });
  document.getElementById("pcalConfirmModal").addEventListener("click", function (e) {
    if (e.target === this) this.classList.remove("pcal-show");
  });

  // ========== Quick-create from day click ==========
  window._pcalQuickCreate = function (dateKey) {
    openForm(null, dateKey);
  };

  // ========== Utility ==========
  function pad(n) { return n < 10 ? "0" + n : "" + n; }
  function escapeHtml(s) {
    if (!s) return "";
    var d = document.createElement("div");
    d.textContent = s;
    return d.innerHTML;
  }
})();

