  fetch(url).then(function(r){return r.json();}).then(function(data){
    if(data.error){grid.innerHTML='&lt;div class="pcal-empty" style="grid-column:1/-1">&lt;p>Gagal.&lt;/p>&lt;/div>';return;}
    allEvents=data.events||[];window._pcalAllEvents=allEvents;
