}
function renderCal(data){
  var evs=data.events||[], ebd={};
  evs.forEach(function(ev){
    var s=new Date(ev.date_begin+'T00:00:00'), e=new Date(ev.date_end+'T00:00:00');
    for(var d=new Date(s);d&lt;=e;d.setDate(d.getDate()+1)){
      var k=d.getFullYear()+'-'+pad(d.getMonth()+1)+'-'+pad(d.getDate());
      if(!ebd[k])ebd[k]=[];ebd[k].push(ev);
    }
  });
