{"CodeContent":"/* =============================================
   Public Calendar – Kalender Kegiatan Gereja
   church_program/static/src/css/public_calendar.css
   ============================================= */

/* ---------- Reset & Variables ---------- */
.pcal {
    --pcal-bg: #0f0e17;
    --pcal-surface: #1a1933;
    --pcal-surface-2: #242244;
    --pcal-border: rgba(255,255,255,.08);
    --pcal-text: #e2e0f0;
    --pcal-text-muted: #9894b8;
    --pcal-accent: #6366f1;
    --pcal-accent-glow: rgba(99,102,241,.25);
    --pcal-today-ring: #a78bfa;
    --pcal-radius: 14px;
    --pcal-radius-sm: 8px;
    --pcal-shadow: 0 4px 24px rgba(0,0,0,.35);

    font-family: 'Inter', 'Segoe UI', system-ui, -apple-system, sans-serif;
    background: var(--pcal-bg);
    color: var(--pcal-text);
    min-height: 100vh;
    line-height: 1.5;
    -webkit-font-smoothing: antialiased;
}

.pcal *,
.pcal *::before,
.pcal *::after { box-sizing: border-box; }

.pcal a { color: inherit; text-decoration: none; }

.pcal-wrap {
    max-width: 1140px;
    margin: 0 auto;
    padding: 0 20px;
}

/* ---------- Hero / Header ---------- */
.pcal-hero {
    background: linear-gradient(135deg, #312e81 0%, #4338ca 40%, #6366f1 100%);
    padding: 48px 0 36px;
    position: relative;
    overflow: hidden;
}

.pcal-hero::before {
    content: '';
    position: absolute;
    width: 340px; height: 340px;
    border-radius: 50%;
    background: radial-gradient(circle, rgba(167,139,250,.18) 0%, transparent 70%);
    top: -80px; right: -60px;
    pointer-events: none;
}

.pcal-hero-content { position: relative; z-index: 1; }

.pcal-hero-icon {
    display: inline-flex;
    align-items: center; justify-content: center;
    width: 52px; height: 52px;
    border-radius: 14px;
    background: rgba(255,255,255,.12);
    backdrop-filter: blur(8px);
    font-size: 22px;
    margin-bottom: 14px;
    color: #e0e7ff;
}

.pcal-hero-title {
    font-size: 28px;
    font-weight: 700;
    margin: 0 0 6px;
    color: #fff;
    letter-spacing: -.3px;
}

.pcal-hero-sub {
    font-size: 15px;
    color: rgba(255,255,255,.7);
    margin: 0;
}

/* ---------- Toolbar ---------- */
.pcal-toolbar {
    display: flex;
    align-items: center;
    justify-content: space-between;
    flex-wrap: wrap;
    gap: 12px;
    padding: 20px 0;
}

.pcal-nav {
    display: flex;
    align-items: center;
    gap: 8px;
}

.pcal-nav-btn {
    display: inline-flex;
    align-items: center; justify-content: center;
    width: 40px; height: 40px;
    border: 1px solid var(--pcal-border);
    border-radius: 10px;
    background: var(--pcal-surface);
    color: var(--pcal-text);
    cursor: pointer;
    font-size: 16px;
    transition: all .2s;
}
.pcal-nav-btn:hover {
    background: var(--pcal-accent);
    border-color: var(--pcal-accent);
    color: #fff;
    box-shadow: 0 0 14px var(--pcal-accent-glow);
}

.pcal-month-label {
    font-size: 20px;
    font-weight: 700;
    min-width: 200px;
    text-align: center;
    letter-spacing: -.2px;
}

.pcal-today-btn {
    padding: 8px 18px;
    border: 1px solid var(--pcal-border);
    border-radius: 10px;
    background: var(--pcal-surface);
    color: var(--pcal-text-muted);
    cursor: pointer;
    font-size: 13px;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: .6px;
    transition: all .2s;
}
.pcal-today-btn:hover {
    background: var(--pcal-accent);
    border-color: var(--pcal-accent);
    color: #fff;
}

/* ---------- Filters ---------- */
.pcal-filters {
    display: flex;
    gap: 10px;
    flex-wrap: wrap;
    margin-bottom: 12px;
}

.pcal-filter-select {
    padding: 8px 14px;
    border-radius: 10px;
    border: 1px solid var(--pcal-border);
    background: var(--pcal-surface);
    color: var(--pcal-text);
    font-size: 13px;
    font-family: inherit;
    appearance: none;
    -webkit-appearance: none;
    background-image: url("data:image/svg+xml,%3Csvg width='10' height='6' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M0 0l5 6 5-6z' fill='%239894b8'/%3E%3C/svg%3E");
    background-repeat: no-repeat;
    background-position: right 12px center;
    padding-right: 32px;
    min-width: 160px;
    cursor: pointer;
    transition: border-color .2s;
}
.pcal-filter-select:focus {
    outline: none;
    border-color: var(--pcal-accent);
    box-shadow: 0 0 0 3px var(--pcal-accent-glow);
}
.pcal-filter-select option {
    background: #1a1933;
    color: #e2e0f0;
}

/* ---------- Calendar Grid ---------- */
.pcal-grid-wrap {
    background: var(--pcal-surface);
    border-radius: var(--pcal-radius);
    border: 1px solid var(--pcal-border);
    overflow: hidden;
    box-shadow: var(--pcal-shadow);
    margin-bottom: 32px;
}

.pcal-grid {
    display: grid;
    grid-template-columns: repeat(7, 1fr);
}

/* Day-of-week header */
.pcal-dow {
    padding: 12px 6px;
    text-align: center;
    font-size: 11px;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    color: var(--pcal-text-muted);
    background: rgba(255,255,255,.03);
    border-bottom: 1px solid var(--pcal-border);
}

.pcal-dow-sun { color: #f87171; }

/* Day cell */
.pcal-day {
    min-height: 110px;
    padding: 6px 8px;
    border-right: 1px solid var(--pcal-border);
    border-bottom: 1px solid var(--pcal-border);
    position: relative;
    transition: background .2s;
    cursor: default;
}
.pcal-day:nth-child(7n) { border-right: none; }

.pcal-day:hover { background: rgba(99,102,241,.06); }

.pcal-day-other {
    opacity: .3;
}

.pcal-day-num {
    display: inline-flex;
    align-items: center; justify-content: center;
    width: 30px; height: 30px;
    border-radius: 50%;
    font-size: 13px;
    font-weight: 600;
    margin-bottom: 4px;
    color: var(--pcal-text);
}

.pcal-day-today .pcal-day-num {
    background: var(--pcal-accent);
    color: #fff;
    box-shadow: 0 0 12px var(--pcal-accent-glow);
    animation: pcal-pulse 2s ease-in-out infinite;
}

@keyframes pcal-pulse {
    0%, 100% { box-shadow: 0 0 12px var(--pcal-accent-glow); }
    50% { box-shadow: 0 0 20px rgba(99,102,241,.45); }
}

.pcal-day-sun .pcal-day-num { color: #f87171; }

/* Event chips */
.pcal-events { display: flex; flex-direction: column; gap: 2px; }

.pcal-event-chip {
    display: flex;
    align-items: center;
    gap: 4px;
    padding: 2px 6px;
    border-radius: 4px;
    font-size: 11px;
    line-height: 1.3;
    cursor: pointer;
    transition: all .15s;
    overflow: hidden;
    white-space: nowrap;
    text-overflow: ellipsis;
    position: relative;
}
.pcal-event-chip:hover {
    filter: brightness(1.2);
    transform: translateY(-1px);
    box-shadow: 0 2px 8px rgba(0,0,0,.3);
}

.pcal-event-chip-dot {
    width: 5px; height: 5px;
    border-radius: 50%;
    flex-shrink: 0;
}

.pcal-event-chip-text {
    overflow: hidden;
    text-overflow: ellipsis;
}

.pcal-more-badge {
    font-size: 10px;
    color: var(--pcal-accent);
    font-weight: 700;
    padding: 2px 0;
    cursor: pointer;
}
.pcal-more-badge:hover { text-decoration: underline; }

/* ---------- Event Detail Modal / Drawer ---------- */
.pcal-modal-overlay {
    position: fixed;
    inset: 0;
    background: rgba(0,0,0,.6);
    backdrop-filter: blur(4px);
    z-index: 9999;
    display: flex;
    align-items: center;
    justify-content: center;
    opacity: 0;
    visibility: hidden;
    transition: all .25s;
}
.pcal-modal-overlay.pcal-show {
    opacity: 1;
    visibility: visible;
}

.pcal-modal {
    background: var(--pcal-surface-2);
    border: 1px solid var(--pcal-border);
    border-radius: var(--pcal-radius);
    padding: 28px;
    max-width: 520px;
    width: 92%;
    max-height: 80vh;
    overflow-y: auto;
    box-shadow: 0 16px 48px rgba(0,0,0,.5);
    transform: translateY(20px);
    transition: transform .25s;
}
.pcal-modal-overlay.pcal-show .pcal-modal {
    transform: translateY(0);
}

.pcal-modal-close {
    float: right;
    width: 32px; height: 32px;
    border: none;
    border-radius: 8px;
    background: rgba(255,255,255,.08);
    color: var(--pcal-text-muted);
    font-size: 16px;
    cursor: pointer;
    display: flex;
    align-items: center; justify-content: center;
    transition: all .2s;
}
.pcal-modal-close:hover {
    background: #ef4444;
    color: #fff;
}

.pcal-modal-title {
    font-size: 20px;
    font-weight: 700;
    margin: 0 0 16px;
    padding-right: 40px;
    color: #fff;
}

.pcal-modal-meta {
    display: flex;
    flex-direction: column;
    gap: 10px;
    margin-bottom: 16px;
}

.pcal-modal-meta-row {
    display: flex;
    align-items: center;
    gap: 10px;
    font-size: 13px;
    color: var(--pcal-text-muted);
}

.pcal-modal-meta-icon {
    width: 28px; height: 28px;
    border-radius: 8px;
    background: rgba(99,102,241,.12);
    display: flex;
    align-items: center; justify-content: center;
    color: var(--pcal-accent);
    font-size: 12px;
    flex-shrink: 0;
}

.pcal-modal-badge {
    display: inline-block;
    padding: 3px 10px;
    border-radius: 6px;
    font-size: 11px;
    font-weight: 600;
}

.pcal-modal-programs {
    margin-top: 14px;
    padding-top: 14px;
    border-top: 1px solid var(--pcal-border);
}

.pcal-modal-programs h4 {
    font-size: 12px;
    text-transform: uppercase;
    letter-spacing: .8px;
    color: var(--pcal-text-muted);
    margin: 0 0 8px;
}

.pcal-prog-chip {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    padding: 5px 12px;
    border-radius: 8px;
    background: rgba(99,102,241,.1);
    border: 1px solid rgba(99,102,241,.2);
    font-size: 12px;
    margin: 0 6px 6px 0;
    color: var(--pcal-text);
}

.pcal-prog-chip-code {
    font-weight: 700;
    color: var(--pcal-accent);
}

/* ---------- Day Detail (mobile: tap day to see all events) ---------- */
.pcal-day-detail-overlay {
    position: fixed;
    inset: 0;
    background: rgba(0,0,0,.6);
    backdrop-filter: blur(4px);
    z-index: 9998;
    display: flex;
    align-items: flex-end;
    justify-content: center;
    opacity: 0;
    visibility: hidden;
    transition: all .25s;
}
.pcal-day-detail-overlay.pcal-show {
    opacity: 1;
    visibility: visible;
}

.pcal-day-detail-sheet {
    background: var(--pcal-surface-2);
    border: 1px solid var(--pcal-border);
    border-radius: var(--pcal-radius) var(--pcal-radius) 0 0;
    padding: 24px 20px 32px;
    width: 100%;
    max-width: 520px;
    max-height: 60vh;
    overflow-y: auto;
    box-shadow: 0 -8px 32px rgba(0,0,0,.4);
    transform: translateY(100%);
    transition: transform .3s;
}
.pcal-day-detail-overlay.pcal-show .pcal-day-detail-sheet {
    transform: translateY(0);
}

.pcal-day-detail-title {
    font-size: 16px;
    font-weight: 700;
    margin: 0 0 14px;
    color: #fff;
}

.pcal-day-detail-event {
    display: flex;
    align-items: flex-start;
    gap: 10px;
    padding: 10px 0;
    border-bottom: 1px solid var(--pcal-border);
    cursor: pointer;
    transition: background .15s;
}
.pcal-day-detail-event:last-child { border-bottom: none; }
.pcal-day-detail-event:hover { background: rgba(99,102,241,.06); }

.pcal-day-detail-dot {
    width: 10px; height: 10px;
    border-radius: 50%;
    flex-shrink: 0;
    margin-top: 5px;
}

.pcal-day-detail-event-name {
    font-size: 14px;
    font-weight: 600;
    color: var(--pcal-text);
}

.pcal-day-detail-event-time {
    font-size: 12px;
    color: var(--pcal-text-muted);
    margin-top: 2px;
}

/* ---------- Legend / Statistics ---------- */
.pcal-legend {
    display: flex;
    flex-wrap: wrap;
    gap: 14px;
    margin-bottom: 24px;
}

.pcal-legend-item {
    display: flex;
    align-items: center;
    gap: 6px;
    font-size: 12px;
    color: var(--pcal-text-muted);
}

.pcal-legend-dot {
    width: 10px; height: 10px;
    border-radius: 50%;
    flex-shrink: 0;
}

/* ---------- Upcoming Events Sidebar ---------- */
.pcal-upcoming {
    background: var(--pcal-surface);
    border: 1px solid var(--pcal-border);
    border-radius: var(--pcal-radius);
    padding: 24px;
    margin-bottom: 32px;
    box-shadow: var(--pcal-shadow);
}

.pcal-upcoming-title {
    font-size: 15px;
    font-weight: 700;
    margin: 0 0 16px;
    display: flex;
    align-items: center;
    gap: 8px;
}
.pcal-upcoming-title i { color: var(--pcal-accent); font-size: 14px; }

.pcal-upcoming-item {
    display: flex;
    gap: 12px;
    padding: 12px 0;
    border-bottom: 1px solid var(--pcal-border);
    cursor: pointer;
    transition: background .15s;
}
.pcal-upcoming-item:last-child { border-bottom: none; }
.pcal-upcoming-item:hover { background: rgba(99,102,241,.04); margin: 0 -12px; padding: 12px; border-radius: 8px; }

.pcal-upcoming-date-box {
    width: 48px;
    text-align: center;
    flex-shrink: 0;
}

.pcal-upcoming-date-day {
    font-size: 22px;
    font-weight: 800;
    color: var(--pcal-accent);
    line-height: 1;
}

.pcal-upcoming-date-month {
    font-size: 10px;
    text-transform: uppercase;
    letter-spacing: .8px;
    color: var(--pcal-text-muted);
}

.pcal-upcoming-info-name {
    font-size: 14px;
    font-weight: 600;
    color: var(--pcal-text);
    margin-bottom: 2px;
}

.pcal-upcoming-info-meta {
    font-size: 12px;
    color: var(--pcal-text-muted);
}

/* ---------- Footer ---------- */
.pcal-footer {
    padding: 24px 0;
    text-align: center;
    font-size: 12px;
    color: var(--pcal-text-muted);
    border-top: 1px solid var(--pcal-border);
}

/* ---------- Loading Spinner ---------- */
.pcal-loading {
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 48px 0;
    gap: 10px;
    color: var(--pcal-text-muted);
    font-size: 14px;
}

.pcal-spinner {
    width: 22px; height: 22px;
    border: 3px solid var(--pcal-border);
    border-top-color: var(--pcal-accent);
    border-radius: 50%;
    animation: pcal-spin .8s linear infinite;
}

@keyframes pcal-spin {
    to { transform: rotate(360deg); }
}

/* ---------- Empty State ---------- */
.pcal-empty {
    text-align: center;
    padding: 48px 24px;
    color: var(--pcal-text-muted);
}

.pcal-empty i {
    font-size: 48px;
    margin-bottom: 16px;
    color: rgba(99,102,241,.3);
}

.pcal-empty h3 {
    font-size: 18px;
    color: var(--pcal-text);
    margin: 0 0 8px;
}

.pcal-empty p {
    font-size: 14px;
    margin: 0;
}

/* ---------- Responsive ---------- */
@media (max-width: 768px) {
    .pcal-hero { padding: 32px 0 24px; }
    .pcal-hero-title { font-size: 22px; }
    .pcal-month-label { font-size: 16px; min-width: 160px; }
    .pcal-toolbar { flex-direction: column; align-items: stretch; }
    .pcal-nav { justify-content: center; }
    .pcal-today-btn { align-self: center; }
    .pcal-filters { justify-content: center; }
    .pcal-filter-select { flex: 1; min-width: 120px; }

    .pcal-day {
        min-height: 60px;
        padding: 4px;
    }
    .pcal-day-num {
        width: 24px; height: 24px;
        font-size: 11px;
    }
    .pcal-event-chip { font-size: 9px; padding: 1px 4px; }
    .pcal-dow { font-size: 10px; padding: 8px 2px; letter-spacing: .5px; }

    .pcal-modal { padding: 20px; }

    .pcal-upcoming { padding: 16px; }
}

@media (max-width: 480px) {
    .pcal-day { min-height: 48px; }
    .pcal-event-chip-text { display: none; }
    .pcal-event-chip { justify-content: center; padding: 3px; }
    .pcal-event-chip-dot { width: 8px; height: 8px; }
}

/* ---------- Scrollbar styling ---------- */
.pcal ::-webkit-scrollbar { width: 6px; }
.pcal ::-webkit-scrollbar-track { background: transparent; }
.pcal ::-webkit-scrollbar-thumb { background: var(--pcal-border); border-radius: 4px; }
.pcal ::-webkit-scrollbar-thumb:hover { background: var(--pcal-accent); }
