.pcal-radio-pill:hover { border-color: var(--pcal-accent); }
.pcal-radio-pill.pcal-active { background: var(--pcal-accent); border-color: var(--pcal-accent); color: #fff; }
.pcal-repeat-mode-row { display: flex; gap: 8px; flex-wrap: wrap; }
.pcal-repeat-mode-pill { padding: 5px 12px; border-radius: 6px; border: 1px solid var(--pcal-border);
    background: var(--pcal-surface); color: var(--pcal-text-muted); cursor: pointer;
    font-size: 12px; transition: all .2s; }
.pcal-repeat-mode-pill.pcal-active { background: rgba(99,102,241,.2); border-color: var(--pcal-accent); color: var(--pcal-text); }

/* Multi-select chips for programs */
.pcal-multi-select { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 6px; }
