/* ---------- Delete Confirm ---------- */
.pcal-confirm-body { text-align: center; padding: 16px 0; }
.pcal-confirm-body i { font-size: 40px; color: #f87171; margin-bottom: 12px; }
.pcal-confirm-body h3 { font-size: 16px; color: #fff; margin: 0 0 8px; }
.pcal-confirm-body p { font-size: 13px; color: var(--pcal-text-muted); margin: 0; }
.pcal-confirm-actions { display: flex; gap: 10px; justify-content: center; margin-top: 20px; }
