{"CodeContent":"/**
 * Public Calendar Management JS
 * Handles CRUD operations for authenticated users.
 * Loaded inline within the QWeb template.
 */
(function () {
  "use strict";

  var root = document.querySelector(".pcal");
  if (!root) return;

  var CAN_MANAGE = root.dataset.canManage === "1";
  var TOKEN = root.dataset.token;
  var PROGRAMS = [];
  try {
    PROGRAMS = JSON.parse(root.dataset.programs || "[]");
  } catch (e) {}

  if (!CAN_MANAGE) return;

  // ========== Toast ==========
  function toast(msg, type) {
    var el = document.createElement("div");
    el.className = "pcal-toast pcal-toast-" + (type || "success");
    el.textContent = msg;
    document.body.appendChild(el);
    requestAnimationFrame(function () {
      el.classList.add("pcal-show");
    });
    setTimeout(function () {
      el.classList.remove("pcal-show");
      setTimeout(function () {
        el.remove();
      }, 400);
    }, 3000);
  }

  // ========== API Helpers ==========
  function apiPost(url, body) {
    return fetch(url, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(body),
    }).then(function (r) {
      return r.json();
    });
  }

  // ========== FAB Button ==========
  var fab = document.createElement("button");
  fab.className = "pcal-fab";
  fab.title = "Buat Kegiatan Baru";
  fab.innerHTML = '<i class="fa fa-plus"></i>';
  fab.addEventListener("click", function () {
    openForm(null);
  });
  document.body.appendChild(fab);

  // ========== Form Modal ==========
  var formOverlay = document.getElementById("pcalFormModal");
  var formEl = document.getElementById("pcalEventForm");

  function closeForm() {
    formOverlay.classList.remove("pcal-show");
  }

  document
    .getElementById("pcalFormClose")
    .addEventListener("click", closeForm);
  formOverlay.addEventListener("click", function (e) {
    if (e.target === formOverlay) closeForm();
  });

  function openForm(ev, prefillDate) {
    var isEdit = !!ev;
    document.getElementById("pcalFormTitle").textContent = isEdit
      ? "Edit Kegiatan"
      : "Buat Kegiatan Baru";
    document.getElementById("pcalFormEventId").value = isEdit ? ev.id : "";

    document.getElementById("pcalFormName").value = isEdit ? ev.name : "";

    // Dates
    var now = new Date();
    var defDate = prefillDate || now.getFullYear() + "-" + pad(now.getMonth()+1) + "-" + pad(now.getDate());
    if (isEdit && ev.date_begin_full) {
      document.getElementById("pcalFormDateBegin").value =
        ev.date_begin_full.substring(0, 16);
    } else {
      document.getElementById("pcalFormDateBegin").value = defDate + "T08:00";
    }
    if (isEdit && ev.date_end_full) {
      document.getElementById("pcalFormDateEnd").value =
        ev.date_end_full.substring(0, 16);
    } else {
      document.getElementById("pcalFormDateEnd").value = defDate + "T10:00";
    }

    // Komisi
    document.getElementById("pcalFormKomisi").value =
      isEdit && ev.komisi_id ? ev.komisi_id : "";

    // Description
    document.getElementById("pcalFormDesc").value =
      isEdit ? (ev.description || "").replace(/<[^>]*>/g, "") : "";

    // Programs multi-select
    var progContainer = document.getElementById("pcalFormPrograms");
    var selectedProgramIds = [];
    if (isEdit && ev.programs) {
      selectedProgramIds = ev.programs.map(function (p) {
        return p.id;
      });
    }
    renderProgramChips(progContainer, selectedProgramIds);

    // Recurrence (only for create)
    var recSection = document.getElementById("pcalRecurrenceSection");
    if (isEdit) {
      recSection.style.display = "none";
    } else {
      recSection.style.display = "";
      document.getElementById("pcalRepeatCheck").checked = false;
      document.getElementById("pcalRecurrenceOpts").classList.remove("pcal-active");
      document.getElementById("pcalRepeatCount").value = "4";
      document.getElementById("pcalRepeatUntil").value = "";
    }
    setRepeatInterval("week");
    setRepeatEndMode("count");

    formOverlay.classList.add("pcal-show");
    setTimeout(function () {
      document.getElementById("pcalFormName").focus();
    }, 100);
  }

  function renderProgramChips(container, selectedIds) {
    var html = "";
    var komisiFilter = document.getElementById("pcalFormKomisi").value;
    var filtered = PROGRAMS;
    if (komisiFilter) {
      var kid = parseInt(komisiFilter);
      filtered = PROGRAMS.filter(function (p) {
        return !p.komisi_id || p.komisi_id === kid;
      });
    }
    filtered.forEach(function (p) {
      var sel = selectedIds.indexOf(p.id) !== -1 ? " pcal-selected" : "";
      html += '<span class="pcal-multi-chip' + sel + '" data-id="' + p.id + '">';
      html += escapeHtml(p.label || p.code + " " + p.name);
      html += "</span>";
    });
    container.innerHTML = html;

    // Click toggle
    container.querySelectorAll(".pcal-multi-chip").forEach(function (chip) {
      chip.addEventListener("click", function () {
        chip.classList.toggle("pcal-selected");
      });
    });
  }

  // Komisi change -> re-render programs
  document
    .getElementById("pcalFormKomisi")
    .addEventListener("change", function () {
      var sel = getSelectedProgramIds();
      renderProgramChips(document.getElementById("pcalFormPrograms"), sel);
    });

  function getSelectedProgramIds() {
    var ids = [];
    document
      .querySelectorAll("#pcalFormPrograms .pcal-multi-chip.pcal-selected")
      .forEach(function (el) {
        ids.push(parseInt(el.dataset.id));
      });
    return ids;
  }

  // Recurrence controls
  var _repeatInterval = "week";
  var _repeatEndMode = "count";

  function setRepeatInterval(val) {
    _repeatInterval = val;
    document
      .querySelectorAll("#pcalIntervalPills .pcal-radio-pill")
      .forEach(function (p) {
        p.classList.toggle("pcal-active", p.dataset.val === val);
      });
  }
  function setRepeatEndMode(val) {
    _repeatEndMode = val;
    document.querySelectorAll("#pcalEndModePills .pcal-repeat-mode-pill").forEach(function (p) {
      p.classList.toggle("pcal-active", p.dataset.val === val);
    });
    document.getElementById("pcalRepeatCountWrap").style.display =
      val === "count" ? "" : "none";
    document.getElementById("pcalRepeatUntilWrap").style.display =
      val === "until" ? "" : "none";
  }

  document.getElementById("pcalRepeatCheck").addEventListener("change", function () {
    document.getElementById("pcalRecurrenceOpts").classList.toggle("pcal-active", this.checked);
  });

  document.querySelectorAll("#pcalIntervalPills .pcal-radio-pill").forEach(function (p) {
    p.addEventListener("click", function () { setRepeatInterval(p.dataset.val); });
  });
  document.querySelectorAll("#pcalEndModePills .pcal-repeat-mode-pill").forEach(function (p) {
    p.addEventListener("click", function () { setRepeatEndMode(p.dataset.val); });
  });

  // Form submit
  formEl.addEventListener("submit", function (e) {
    e.preventDefault();
    var eventId = document.getElementById("pcalFormEventId").value;
    var isEdit = !!eventId;

    var body = {
      name: document.getElementById("pcalFormName").value.trim(),
      date_begin: document.getElementById("pcalFormDateBegin").value,
      date_end: document.getElementById("pcalFormDateEnd").value,
      komisi_id: document.getElementById("pcalFormKomisi").value || null,
      description: document.getElementById("pcalFormDesc").value,
      program_ids: getSelectedProgramIds(),
    };

    if (!body.name) {
      toast("Nama kegiatan wajib diisi", "error");
      return;
    }

    // Recurrence (create only)
    if (!isEdit && document.getElementById("pcalRepeatCheck").checked) {
      body.repeat_enabled = true;
      body.repeat_interval = _repeatInterval;
      if (_repeatEndMode === "count") {
        body.repeat_count = parseInt(document.getElementById("pcalRepeatCount").value) || 4;
      } else {
        body.repeat_until = document.getElementById("pcalRepeatUntil").value;
      }
    }

    var url = isEdit
      ? "/kalender/" + TOKEN + "/event/" + eventId + "/update"
      : "/kalender/" + TOKEN + "/event/create";

    var submitBtn = document.getElementById("pcalFormSubmit");
    submitBtn.disabled = true;
    submitBtn.textContent = "Menyimpan...";

    apiPost(url, body)
      .then(function (data) {
        submitBtn.disabled = false;
        submitBtn.textContent = "Simpan";
        if (data.error) {
          toast("Gagal: " + data.error, "error");
          return;
        }
        closeForm();
        var msg = isEdit ? "Kegiatan diperbarui" : "Kegiatan dibuat";
        if (data.count && data.count > 1)
          msg += " (" + data.count + " event berulang)";
        toast(msg, "success");
        // Refresh calendar
        if (typeof window._pcalRefresh === "function") window._pcalRefresh();
      })
      .catch(function () {
        submitBtn.disabled = false;
        submitBtn.textContent = "Simpan";
        toast("Terjadi kesalahan jaringan", "error");
      });
  });

  // ========== Edit & Delete from Detail Modal ==========
  window._pcalEditEvent = function (eventId) {
    var ev =
      window._pcalAllEvents &&
      window._pcalAllEvents.find(function (e) {
        return e.id === eventId;
      });
    if (!ev) return;
    document.getElementById("pcalModal").classList.remove("pcal-show");
    openForm(ev);
  };

  window._pcalDeleteEvent = function (eventId) {
    var ev =
      window._pcalAllEvents &&
      window._pcalAllEvents.find(function (e) {
        return e.id === eventId;
      });
    if (!ev) return;
    document.getElementById("pcalModal").classList.remove("pcal-show");

    // Show confirm dialog
    var confirmOverlay = document.getElementById("pcalConfirmModal");
    document.getElementById("pcalConfirmName").textContent = ev.name;
    confirmOverlay.dataset.eventId = eventId;
    confirmOverlay.classList.add("pcal-show");
  };

  // Confirm delete
  document.getElementById("pcalConfirmDelete").addEventListener("click", function () {
    var confirmOverlay = document.getElementById("pcalConfirmModal");
    var eventId = confirmOverlay.dataset.eventId;
    confirmOverlay.classList.remove("pcal-show");

    apiPost("/kalender/" + TOKEN + "/event/" + eventId + "/delete", {})
      .then(function (data) {
        if (data.error) {
          toast("Gagal menghapus: " + data.error, "error");
          return;
        }
        toast("Kegiatan dihapus", "success");
        if (typeof window._pcalRefresh === "function") window._pcalRefresh();
      })
      .catch(function () {
        toast("Terjadi kesalahan jaringan", "error");
      });
  });

  document.getElementById("pcalConfirmCancel").addEventListener("click", function () {
    document.getElementById("pcalConfirmModal").classList.remove("pcal-show");
  });
  document.getElementById("pcalConfirmModal").addEventListener("click", function (e) {
    if (e.target === this) this.classList.remove("pcal-show");
  });

  // ========== Quick-create from day click ==========
  window._pcalQuickCreate = function (dateKey) {
    openForm(null, dateKey);
  };

  // ========== Utility ==========
  function pad(n) { return n < 10 ? "0" + n : "" + n; }
  function escapeHtml(s) {
    if (!s) return "";
    var d = document.createElement("div");
    d.textContent = s;
    return d.innerHTML;
  }
})();
","Description":"Standalone JS module for calendar CRUD operations: FAB button, create/edit form, recurrence controls, delete confirmation, program multi-select, and toast notifications. Wired up via global window functions from the main calendar JS.","IsArtifact":false,"Overwrite":false,"TargetFile":"/Volumes/980PRO/OpenERP/addons/church-management-system/odoo-addons-16/church_program/static/src/js/public_calendar_manage.js","toolAction":"Creating management JS","toolSummary":"CRUD JavaScript"}

{"CodeContent":"<?xml version="1.0" encoding="utf-8"?>
<odoo>
    <template id="public_calendar_not_found" name="Kalender - Tidak Ditemukan">
        <t t-call="website.layout">
            <div class="pcal">
                <div class="pcal-wrap" style="padding:80px 20px;text-align:center;">
                    <div class="pcal-empty">
                        <i class="fa fa-calendar-times-o"/>
                        <h3>Kalender Tidak Ditemukan</h3>
                        <p>Link kalender tidak valid atau halaman ini belum diaktifkan.</p>
                    </div>
                </div>
            </div>
        </t>
    </template>

    <template id="public_calendar_page" name="Kalender Kegiatan - Public">
        <t t-call="website.layout">
            <t t-set="can_manage_str" t-value="'1' if can_manage else '0'"/>
            <div class="pcal" t-att-data-token="token" t-att-data-init-year="init_year"
                 t-att-data-init-month="init_month" t-att-data-can-manage="can_manage_str"
                 t-att-data-programs="program_list_json">

                <div class="pcal-hero">
                    <div class="pcal-wrap pcal-hero-content">
                        <div class="pcal-hero-icon"><i class="fa fa-calendar"/></div>
                        <h1 class="pcal-hero-title">Kalender Kegiatan</h1>
                        <p class="pcal-hero-sub"><t t-esc="company.name"/> — <t t-esc="fiscalyear.name"/></p>
                        <t t-if="can_manage">
                            <div class="pcal-auth-badge"><i class="fa fa-shield"/> <t t-esc="user_name"/> — Mode Kelola</div>
                        </t>
                    </div>
                </div>

                <div class="pcal-wrap">
                    <div class="pcal-toolbar">
                        <div class="pcal-nav">
                            <button class="pcal-nav-btn" id="pcalPrevMonth"><i class="fa fa-chevron-left"/></button>
                            <span class="pcal-month-label" id="pcalMonthLabel">—</span>
                            <button class="pcal-nav-btn" id="pcalNextMonth"><i class="fa fa-chevron-right"/></button>
                        </div>
                        <button class="pcal-today-btn" id="pcalToday">Hari Ini</button>
                    </div>
                    <div class="pcal-filters">
                        <select class="pcal-filter-select" id="pcalFilterBidang">
                            <option value="">Semua Bidang</option>
                            <t t-foreach="bidang_list" t-as="bid" t-key="bid.id">
                                <option t-att-value="bid.id"><t t-esc="bid.name"/></option>
                            </t>
                        </select>
                        <select class="pcal-filter-select" id="pcalFilterKomisi">
                            <option value="">Semua Komisi</option>
                            <t t-foreach="komisi_list" t-as="kom" t-key="kom.id">
                                <option t-att-value="kom.id"><t t-esc="kom.name"/></option>
                            </t>
                        </select>
                    </div>
                    <div class="pcal-grid-wrap"><div class="pcal-grid" id="pcalGrid"></div></div>
                    <div class="pcal-legend" id="pcalLegend"></div>
                    <div class="pcal-upcoming" id="pcalUpcoming">
                        <div class="pcal-upcoming-title"><i class="fa fa-clock-o"/><span>Kegiatan Mendatang</span></div>
                        <div id="pcalUpcomingList"></div>
                    </div>
                </div>

                <div class="pcal-footer"><div class="pcal-wrap"><p>© <t t-esc="fiscalyear.name"/> <t t-esc="company.name"/></p></div></div>

                <!-- Detail Modal -->
                <div class="pcal-modal-overlay" id="pcalModal">
                    <div class="pcal-modal">
                        <button class="pcal-modal-close" id="pcalModalClose"><i class="fa fa-times"/></button>
                        <h3 class="pcal-modal-title" id="pcalModalTitle">—</h3>
                        <div class="pcal-modal-meta" id="pcalModalMeta"></div>
                        <div class="pcal-modal-programs" id="pcalModalPrograms" style="display:none;"></div>
                        <div class="pcal-modal-actions" id="pcalModalActions" style="display:none;"></div>
                    </div>
                </div>

                <!-- Day Detail -->
                <div class="pcal-day-detail-overlay" id="pcalDayDetail">
                    <div class="pcal-day-detail-sheet">
                        <button class="pcal-modal-close" id="pcalDayDetailClose" style="float:right;"><i class="fa fa-times"/></button>
                        <h3 class="pcal-day-detail-title" id="pcalDayDetailTitle">—</h3>
                        <div id="pcalDayDetailList"></div>
                    </div>
                </div>

                <!-- Form Modal (auth only) -->
                <div class="pcal-modal-overlay" id="pcalFormModal">
                    <div class="pcal-modal pcal-form-modal">
                        <button class="pcal-modal-close" id="pcalFormClose"><i class="fa fa-times"/></button>
                        <h3 class="pcal-form-title" id="pcalFormTitle">Buat Kegiatan Baru</h3>
                        <form id="pcalEventForm" autocomplete="off">
                            <input type="hidden" id="pcalFormEventId" value=""/>
                            <div class="pcal-form-group">
                                <label class="pcal-form-label">Nama Kegiatan *</label>
                                <input class="pcal-form-input" id="pcalFormName" required="required" placeholder="Contoh: Rapat Komisi"/>
                            </div>
                            <div class="pcal-form-row">
                                <div class="pcal-form-group">
                                    <label class="pcal-form-label">Mulai</label>
                                    <input type="datetime-local" class="pcal-form-input" id="pcalFormDateBegin"/>
                                </div>
                                <div class="pcal-form-group">
                                    <label class="pcal-form-label">Selesai</label>
                                    <input type="datetime-local" class="pcal-form-input" id="pcalFormDateEnd"/>
                                </div>
                            </div>
                            <div class="pcal-form-group">
                                <label class="pcal-form-label">Komisi</label>
                                <select class="pcal-form-select" id="pcalFormKomisi">
                                    <option value="">— Pilih Komisi —</option>
                                    <t t-foreach="komisi_list" t-as="kom" t-key="kom.id">
                                        <option t-att-value="kom.id"><t t-esc="kom.name"/></option>
                                    </t>
                                </select>
                            </div>
                            <div class="pcal-form-group">
                                <label class="pcal-form-label">Program Kerja Terkait</label>
                                <div class="pcal-multi-select" id="pcalFormPrograms"></div>
                            </div>
                            <div class="pcal-form-group">
                                <label class="pcal-form-label">Keterangan</label>
                                <textarea class="pcal-form-textarea" id="pcalFormDesc" rows="3"></textarea>
                            </div>
                            <!-- Recurrence -->
                            <div class="pcal-form-recurrence" id="pcalRecurrenceSection">
                                <label class="pcal-form-check">
                                    <input type="checkbox" id="pcalRepeatCheck"/>
                                    <span>🔁 Event Berulang</span>
                                </label>
                                <div class="pcal-recurrence-opts" id="pcalRecurrenceOpts">
                                    <div class="pcal-form-group">
                                        <label class="pcal-form-label">Interval</label>
                                        <div class="pcal-radio-group" id="pcalIntervalPills">
                                            <span class="pcal-radio-pill" data-val="day">Harian</span>
                                            <span class="pcal-radio-pill pcal-active" data-val="week">Mingguan</span>
                                            <span class="pcal-radio-pill" data-val="month">Bulanan</span>
                                        </div>
                                    </div>
                                    <div class="pcal-form-group">
                                        <label class="pcal-form-label">Berakhir</label>
                                        <div class="pcal-repeat-mode-row" id="pcalEndModePills">
                                            <span class="pcal-repeat-mode-pill pcal-active" data-val="count">Jumlah</span>
                                            <span class="pcal-repeat-mode-pill" data-val="until">Sampai Tanggal</span>
                                        </div>
                                    </div>
                                    <div class="pcal-form-group" id="pcalRepeatCountWrap">
                                        <label class="pcal-form-label">Berulang (kali)</label>
                                        <input type="number" class="pcal-form-input" id="pcalRepeatCount" value="4" min="2" max="365"/>
                                    </div>
                                    <div class="pcal-form-group" id="pcalRepeatUntilWrap" style="display:none;">
                                        <label class="pcal-form-label">Sampai Tanggal</label>
                                        <input type="date" class="pcal-form-input" id="pcalRepeatUntil"/>
                                    </div>
                                </div>
                            </div>
                            <div class="pcal-form-footer">
                                <button type="button" class="pcal-btn pcal-btn-secondary" onclick="document.getElementById('pcalFormModal').classList.remove('pcal-show')">Batal</button>
                                <button type="submit" class="pcal-btn pcal-btn-primary" id="pcalFormSubmit">Simpan</button>
                            </div>
                        </form>
                    </div>
                </div>

                <!-- Delete Confirm Modal -->
                <div class="pcal-modal-overlay" id="pcalConfirmModal">
                    <div class="pcal-modal" style="max-width:400px;">
                        <div class="pcal-confirm-body">
                            <i class="fa fa-trash"/>
                            <h3>Hapus Kegiatan?</h3>
                            <p><span id="pcalConfirmName"></span></p>
                        </div>
                        <div class="pcal-confirm-actions">
                            <button class="pcal-btn pcal-btn-secondary" id="pcalConfirmCancel">Batal</button>
                            <button class="pcal-btn pcal-btn-danger" id="pcalConfirmDelete"><i class="fa fa-trash"/> Hapus</button>
                        </div>
                    </div>
                </div>

                <!-- Main Calendar JS -->
                <script type="text/javascript">
(function(){
'use strict';
var MN=['Januari','Februari','Maret','April','Mei','Juni','Juli','Agustus','September','Oktober','November','Desember'];
var DN=['Sen','Sel','Rab','Kam','Jum','Sab','Min'];
var MC=3, root=document.querySelector('.pcal'), token=root.dataset.token;
var cY=parseInt(root.dataset.initYear), cM=parseInt(root.dataset.initMonth);
var canManage=root.dataset.canManage==='1';
var allEvents=[]; window._pcalAllEvents=allEvents;
var grid=document.getElementById('pcalGrid'), monthLabel=document.getElementById('pcalMonthLabel');
var legend=document.getElementById('pcalLegend'), upList=document.getElementById('pcalUpcomingList');
var modal=document.getElementById('pcalModal'), mTitle=document.getElementById('pcalModalTitle');
var mMeta=document.getElementById('pcalModalMeta'), mProgs=document.getElementById('pcalModalPrograms');
var mActions=document.getElementById('pcalModalActions');
var dayDetail=document.getElementById('pcalDayDetail'), ddTitle=document.getElementById('pcalDayDetailTitle');
var ddList=document.getElementById('pcalDayDetailList');

function pad(n){return n&lt;10?'0'+n:''+n;}
function fmtDate(s){if(!s)return '';var d=new Date(s);return d.getDate()+' '+MN[d.getMonth()]+' '+d.getFullYear();}
function fmtTime(s){if(!s)return '';var d=new Date(s);return pad(d.getHours())+':'+pad(d.getMinutes());}
function esc(s){if(!s)return '';var d=document.createElement('div');d.textContent=s;return d.innerHTML;}

window._pcalRefresh=fetchEvents;
function fetchEvents(){
  var bi=document.getElementById('pcalFilterBidang').value;
  var ki=document.getElementById('pcalFilterKomisi').value;
  var url='/kalender/'+token+'/events?year='+cY+'&amp;month='+cM;
  if(bi)url+='&amp;bidang_id='+bi; if(ki)url+='&amp;komisi_id='+ki;
  grid.innerHTML='&lt;div class="pcal-loading" style="grid-column:1/-1">&lt;div class="pcal-spinner">&lt;/div>&lt;span>Memuat...&lt;/span>&lt;/div>';
  fetch(url).then(function(r){return r.json();}).then(function(data){
    if(data.error){grid.innerHTML='&lt;div class="pcal-empty" style="grid-column:1/-1">&lt;p>Gagal.&lt;/p>&lt;/div>';return;}
    allEvents=data.events||[];window._pcalAllEvents=allEvents;
    renderCal(data);renderLeg(allEvents);renderUp(allEvents);
  }).catch(function(){grid.innerHTML='&lt;div class="pcal-empty" style="grid-column:1/-1">&lt;p>Gagal memuat.&lt;/p>&lt;/div>';});
}
function renderCal(data){
  var evs=data.events||[], ebd={};
  evs.forEach(function(ev){
    var s=new Date(ev.date_begin+'T00:00:00'), e=new Date(ev.date_end+'T00:00:00');
    for(var d=new Date(s);d&lt;=e;d.setDate(d.getDate()+1)){
      var k=d.getFullYear()+'-'+pad(d.getMonth()+1)+'-'+pad(d.getDate());
      if(!ebd[k])ebd[k]=[];ebd[k].push(ev);
    }
  });
  var fd=new Date(cY,cM-1,1), ld=new Date(cY,cM,0);
  var so=(fd.getDay()+6)%7;var cs=new Date(fd);cs.setDate(cs.getDate()-so);
  var ce=new Date(ld);if(ld.getDay()!==0)ce.setDate(ce.getDate()+(7-ld.getDay()));
  var today=new Date();today.setHours(0,0,0,0);
  var h='';
  DN.forEach(function(n,i){h+='&lt;div class="pcal-dow'+(i===6?' pcal-dow-sun':'')+'">'+n+'&lt;/div>';});
  var d=new Date(cs);
  while(d&lt;=ce){
    var k=d.getFullYear()+'-'+pad(d.getMonth()+1)+'-'+pad(d.getDate());
    var isCur=d.getMonth()===(cM-1)&amp;&amp;d.getFullYear()===cY;
    var isT=d.getFullYear()===today.getFullYear()&amp;&amp;d.getMonth()===today.getMonth()&amp;&amp;d.getDate()===today.getDate();
    var isSun=d.getDay()===0;
    var cls='pcal-day';if(!isCur)cls+=' pcal-day-other';if(isT)cls+=' pcal-day-today';if(isSun)cls+=' pcal-day-sun';
    var de=ebd[k]||[];
    h+='&lt;div class="'+cls+'" data-date="'+k+'" onclick="window._pcalDayClick(\''+k+'\')">';
    h+='&lt;div class="pcal-day-num">'+d.getDate()+'&lt;/div>&lt;div class="pcal-events">';
    var sh=Math.min(de.length,MC);
    for(var i=0;i&lt;sh;i++){var ev=de[i];var bg=ev.bidang_bg_color||'#6366f1';var fg=ev.bidang_fg_color||'#fff';
      h+='&lt;div class="pcal-event-chip" style="background:'+bg+'22;color:'+fg+';" onclick="event.stopPropagation();window._pcalShowEvent('+ev.id+');">';
      h+='&lt;span class="pcal-event-chip-dot" style="background:'+bg+';">&lt;/span>&lt;span class="pcal-event-chip-text">'+esc(ev.name)+'&lt;/span>&lt;/div>';}
    if(de.length>MC)h+='&lt;div class="pcal-more-badge">+'+(de.length-MC)+' lainnya&lt;/div>';
    h+='&lt;/div>&lt;/div>';d.setDate(d.getDate()+1);
  }
